/* FANUC SVGN alarm codes — generated by tools/fetch-alarms.js,
 * DO NOT EDIT; re-run the tool instead. 321 codes, 2026-10-22.
 * Source: http://linuxsand.info/fanuc/ — internal reference copy, by permission. */
(function (global) {
  var data = {
    "001": "SVGN-001 Serious Internal error\nCause:  Internal Servo Gun error.\nRemedy:  Record error and report to hotline.",
    "002": "SVGN-002 No sysvar pointer\nCause:  This is an internal system error.\nRemedy:  Record error and report to hotline.",
    "003": "SVGN-003 No global variables\nCause:  This is an internal system error.\nRemedy:  Record error and report to hotline.",
    "004": "SVGN-004 Unable to Allocate Memory\nCause:  A failure occurred while allocating memory.\nRemedy:  Check amount of memory being used by the system. Perform a cold start on the controller. If the problem still exists,\ndocument the events that led to the error, and contact your FANUC technical representative.",
    "005": "SVGN-005 Wrong TPP inst. format\nCause:  An internal servogun program error has occurred.\nRemedy:  Repower, perform a Controlled start, and then back to Cold start. This action re-generates the internal servogun\nprogram and may correct the problem. If the problem persists, document the events that led to the error, and contact\nyour FANUC technical representative.",
    "006": "SVGN-006 Another TASK used this equip.\nCause:  Another TPP specified this equipment and now executing or paused.\nRemedy:  Force abort another TPP.",
    "008": "SVGN-008 Syntax error\nCause:  Instruction syntax error. This instruction is for air gun spot.\nRemedy:  Reteach the instruction. Reteach servo gun SPOT instruction.",
    "009": "SVGN-009 Motion Group config. mismatch\nCause:  The robot group and/or gun group are not enabled, in the group mask of this teach pendant program.\nRemedy:  Determine the robot group number and gun group number for this equipment, then re-create the program, with these\ngroups enabled.",
    "010": "SVGN-010 Invalid SG group config.\nCause:  An invalid servo gun group number (greater than total number of groups) has been assigned to this servogun\n(equipment).\nRemedy:  Check the group number assigned to this servogun (equipment).",
    "011": "SVGN-011 Can not execute instruction(s).\nCause:  Incremental, offset or tool offset instructions can not execute with servo gun SPOT instruction at the same program\nline.\nRemedy:  Delete the incompatible motion option.",
    "012": "SVGN-012 Invalid value for index\nCause:  The register index specified in the instruction is invalid.\nRemedy:  Check the index value.",
    "013": "SVGN-013 Pressure exceeds limit\nCause:  The Pressure specified in the pressure schedule, or pressure instruction, exceeds the Max Pressure for the gun.\nRemedy:  Reduce the Pressure in the pressure schedule or program, or increase the Max Pressure item on the Servo Gun General\nSETUP screen. Confirm that the new pressure value does not exceed the mechanical limitation of the gun.",
    "015": "SVGN-015 Setup Configuration error\nCause:  Pointer to gun, schedule, backup or distance data is invalid.\nRemedy:  Check the servo gun configuration data. Document the events that led to the error, and call your FANUC technical\nrepresentative.",
    "016": "SVGN-016 Specified pressure too low\nCause:  The pressure specified in the pressure schedule or pressure instruction is lower than the lowest reachable pressure on\nthe calibration curve.\nRemedy:  Increase the Weld Pressure, set weld pressure = 0, or recalibrate pressure. Note 1: when weld pressure = 0, the\nminimum possible pressure (actual tip force may not be 0) is used. SVGN-016 will not be posted even if the\ncalibration curve does not contain a point where weld pressure = 0. Note 2: add a calibration point at or below the\nspecified pressure to ensure the gun can achieve the low pressure. Note 3: reducing the contact speed might make it\npossible to achieve lower pressures.",
    "017": "SVGN-017 Invalid pressure coefficient\nCause:  Single-segment calibration method is enabled and prm_a1 is invalid (less than 0.0001 OR greater than 100.0).\nRemedy:  Change the calibration method to the multi-linear segment method if possible. Do this by setting the sysvars\n$sgsyscfg.$cal_model = 12 and $sgsyscfg.$frc2spd_cnv = 3, then perform the pressure calibration again.",
    "018": "SVGN-018 Illegal torque limit value\nCause:  The torque value is illegal (less than $sgsyscfg.$minimum_trq OR greater than max rated torque). This alarm can\noccur at the following times: SPOT[], PRESS_MOTN[], or PRESS[]kgf execution.\nRemedy:  Confirm that the pressure calibration data is valid.",
    "019": "SVGN-019 Pressure shortage: Gun%d\nCause:  Same as SVGN-020, but severity is WARN. Note: SVGN-019 can occur during autotuning or if $sgsyscfg.$pst_ertype\n= 1; SVGN-020 occurs otherwise.\nRemedy:  See remedy for SVGN-020.",
    "020": "SVGN-020 Pressure shortage%d: Gun%d\nCause:  The SPOT, PRESS_MOTN or TIPDRESS, instruction failed because gun closure was not detected(1) or gun pressure\nwas unstable(2). The number after pressure shortage (1 or 2) identifies the failure type. Scan the list below for the\ncause that most nearly matches the condition at hand, then refer to the remedy for that cause.\nShortage 1) The instruction completed - gun tip moved to the pushing depth position - without torque increasing to the\ngun close detection value (1/2 Std Overtorque Value).\n1A) If gun moved to current close axis limit (ClosLim from SVGN-177) without achieving pressure, then axis\nlimit is too small.\n1B) Pushing depth parameter in pressure schedule is not large enough to overcome gun bending at target pressure\nplus tip wear amount since last measurement.\n1C) Part thickness parameter (Thk from SVGN-177) is much larger than actual part thickness.\n1D) Gun zero master position is incorrect (if tips are worn and user chooses to not use tip wear comp, then start\nwith 1B).\n1E) Gun close detection torque may be excessive (or larger than Max Motor torque) due to a large restriction in\ngun mechanism.\nShortage 2) The torque for pressuring varied from the target value. There are (2) likely causes:\n2A) Target pressure is at very low or high end of gun operating range (tips are likely touching part).\n2B) Friction in gun mechanism has increased considerably since gun was autotuned (tips are likely NOT\ntouching part).\nRemedy:\nShortage 1)\n1A) When tip wear compensation is used, close axis limit is adjusted to avoid over-stroking gun (ClosLim\nbecomes smaller than StdLim when caps are worn). To extend axis limit, change tips, then run tip wear comp\nupdate program when using tip wear comp. Next, check the original close limit (StdLim) setting on servo gun\nsetup screen and adjust if not correct.\n1B) Increase pushing depth in pressure schedule (set $sgsyscfg.$sho_pshdpth=TRUE to see pushing depth\nparameter).\n1C) Reduce part thickness in the pressure schedule so it is closer to actual part thickness.\n1D) If using tip wear compensation, re-master the gun by running the tip wear compensation update program.\nOtherwise, refer to 1B or re-master the gun with new tips from the gun master screen.\n1E) Adjust the gun mechanism to relieve the restriction. Re-tune the gun (autotune) and calibrate pressure after\nadjustment.\nShortage 2)\n2A) Re-tune the gun (autotune) then confirm pressure calibration. If problem persists, or if the alarm occurs\nduring tip wear measurement, autotune with Initial Filter set to a value between 10-30. To see Initial Filter item,\nset $sgsyscfg.$sho_atn_cfg=TRUE then press enter on Auto Tune item from Gun Setup Utility before tuning.\n2B) Re-tune the gun (autotune) to adjust the gun close detection limit, then confirm pressure calibration. If\nrequired, adjust the gun mechanism to relieve the cause of friction increase.",
    "021": "SVGN-021 Uninitialized BU condition\nCause:  The BU schedule number (condition) is not initialized or is invalid.\nRemedy:  Set a valid backup schedule number (greater than or equal to 0, AND less than or equal to $sgsyscfg.$back_elm) into\nthe instruction in the teach pendant program.",
    "022": "SVGN-022 Uninitialized Pres. condition\nCause:  The pressure schedule number (condition) is not initialized or is invalid.\nRemedy:  Set a valid Pressure schedule number (greater than or equal to 1, AND less than or equal to $sgsyscfg.$sch_elm) into\nthe instruction in the teach pendant program.",
    "023": "SVGN-023 Incomplete Pressure calibration\nCause:  Incomplete pressure calibration.\nRemedy:  Go to the Servo Gun General SETUP screen, select Pressure calibration, and perform pre ssure calibration procedure.",
    "024": "SVGN-024 Incomplete Wear Down calibration\nCause:  Tip Wear Compensation setup (calibration) is not complete.\nRemedy:  Perform the Tip Wear Setup procedure. Consult the Servo Gun Manual for details on this procedure.",
    "025": "SVGN-025 Illegal BU condition number\nCause:  Invalid BU schedule (condition) number (greater than $sgsyscfg.$back_elm, or less than 0).\nRemedy:  Specify a backup condition number within the range above.",
    "026": "SVGN-026 Illegal P condition number\nCause:  Invalid P schedule (condition) number ( greater than $sgsyscfg.$sch_elm, or less than 1 ).\nRemedy:  Specify a pressure condition number within the range above.",
    "027": "SVGN-027 Untaught element encountered\nCause:  Some program elements (like positional data for example) have not been recorded.\nRemedy:  Enter data for the missing program elements.",
    "028": "SVGN-028 Pos. type is JOINT\nCause:  Position type is JOINT.\nRemedy:  Change position type to XYZWPR.",
    "029": "SVGN-029 Over max motor torque value\nCause:  The motor torque required to achieve the pressure specified in the pressure schedule or pressure instruction exceeds the\nMax Torque value specified on the Servogun SETUP screen.\nRemedy:\n1.  Reduce the Pressure value.\n2.  Check Pressure Calibration data.\n3.  Calibrate Pressure again if the data is incorrect.\n4.  Increase the Max Motor Torque value on the Servo Gun General SETUP screen, if possible. Note: motor torque\nvalue on the General SETUP screen can be regarded as a fractional percentage of the maximum allowable torque.\nThe screen will not allow this value to be set larger than amp + motor rating.",
    "030": "SVGN-030 Tip Stick detection\nCause:  Tip stick detection DI is ON.\nRemedy:  Jog the gun open or use a tool to separate the tip from the part, if the tip is stuck. If the tip is not stuck, then determine\nwhy the tip stick input is on.",
    "031": "SVGN-031 Tear Off is executing\nCause:  When tear off function is executing, program cannot be started.\nRemedy:  Restart program after tear off function finished.",
    "032": "SVGN-032 Tip increased error(Gun)\nCause:  The measured tip wear on the gun side (moving tip) indicates that the tip has grown by an amount greater than the Gun\nIncreased Error(mm) setting.\nRemedy:  First confirm the condition of the tip. If the tip is not ok, then replace it, and perform tip wear measurement again. If a\nchip from tip dressing remains on the tip, remove this chip then re-measure the tip wear. If new tips were installed\nafter the previous tip wear measurement, be sure the tip wear update program was run with the New Tips Parameter set\nto (1) in the Call instruction for the tip wear macro. If this parameter was not set correctly, then press fault reset and\nrun the tip wear update program again with the New Tips Parameter set to (1). If the tip is OK and the new tip\nparameter was set correctly, then perform the tip wear measurement again. Observe the gun closely during this\noperation. Be sure the tips touch during the 1st step of the tip wear measurement and be sure the gun tip touches the\nfixture during the 2nd step (if used). If the gun tip does not close fully during either step, then the gun friction has\nprobably increased. To compensate, run Autotuning then Pressure Calibration and perform the tip wear setup\nprocedure again with new tips. Inspect the gun to find the reason for the increase in friction. If both steps of the\nmeasurement perform correctly then it might be necessary to increase the value of the Increase Error(mm) setting for\nthe robot side tip. Do this on the Tip Wear Detection screen (SETUP-SERVO GUN-GENERAL SETUP).",
    "033": "SVGN-033 Tip increased error(Robot)\nCause:  The measured tip wear on the robot side (stationary tip) indicates that the tip has grown by an amount greater than the\nRobot Increased Error(mm) setting.\nRemedy:  First confirm the condition of the tip. If the tip is not ok, then replace it, and perform tip wear measurement again. If a\nchip from tip dressing remains on the tip, remove this chip then re-measure the tip wear. If new tips were installed\nafter the previous tip wear measurement, be sure the tip wear update program was run with the New Tips Parameter set\nto (1) in the Call instruction for the tip wear macro. If this parameter was not set correctly, then press fault reset and\nrun the tip wear update program again with the New Tips Parameter set to (1). If the tip is OK and the new tip\nparameter was set correctly, then perform the tip wear measurement again. Observe the gun closely during this\noperation. Be sure the tips touch during the 1st step of the tip wear measurement and be sure the gun tip touches the\nfixture during the 2nd step (if used). If the gun tip does not close fully during either step, then the gun friction has\nprobably increased. To compensate, run Autotuning then Pressure Calibration and perform the tip wear setup\nprocedure again with new tips. Inspect the gun to find the reason for the increase in friction. If both steps of the\nmeasurement perform correctly then it might be necessary to increase the value of the Increase Error(mm) setting for\nthe robot side tip. Do this on the Tip Wear Detection screen (SETUP-SERVO GUN-GENERAL SETUP).",
    "034": "SVGN-034 Excessive robot tip difference.\nCause:  The Tip Wear difference between the robot tips on the dual gun exceeds the specified tolerance.\nRemedy:  Replace or dress the tips (and tip holder if necessary) and run the tip wear update program for each gun. Alternatively,\nincrease the difference tolerance in the Tip Wear Detection screen. (Press MENUS. Select SETUP. Select SERVO\nGUN. Select GENERAL SETUP.)",
    "035": "SVGN-035 Pressure enable time out\nCause:  The pressure enable signal (input) did not turn on before the wait time expired.\nRemedy:  Determine why the pressure enable signal did not turn on. Or, increase the value of time\nout($SPOTEQSETUP[].$PEN_TMOUT) if it is too short.",
    "036": "SVGN-036 Comp confirmation time out\nCause:  The comp confirmation signal (input) did not turn on before the wait time expired.\nRemedy:  Check the reason that the comp confirmation signal is off. Or, increase the value of time\nout($SPOTEQSETUP[].$NSE_TMOUT), if it is too short.",
    "037": "SVGN-037 Illegal pressure enable signal\nCause:  The pressure enable signal number is illegal.\nRemedy:  Map the pressure enable input to a valid input index via ($SPOTEQIO[].$DI_PEN_I).",
    "038": "SVGN-038 Illegal comp confirmation signal\nCause:  The comp confirmation signal number is illegal.\nRemedy:  Map the comp confirmation input to a valid input index via ($SPOTEQIO[].$DI_NSE_I).",
    "039": "SVGN-039 Thk:%s NOT intol(expect:%s).\nCause:  Same as SVGN-040, but with a WARN severity.\nRemedy:  See SVGN-040.",
    "040": "SVGN-040 Thk:%s NOT intol(expect:%s).\nCause:  The Measured part thickness deviates from the specified value more than the Under or Over thickness limit(mm). The\npart might be out-of-tolerance.\nRemedy:  Check the master position for the gun axis and make sure the tips touch at the zero position (+/- 0.1mm). Confirm that\ntip wear and gun sag compensation are enabled and that the compensation values are correct. Check the part or re-enter\nthe part thickness in the pressure schedule. Alternatively, increase the Under and Over thickness limits in the Part\nThickness check screen found on the Servo Gun General Setup screen. Resume the program, to retry the measurement.\nPerform thickness check calibration again, if the problem persists.",
    "041": "SVGN-041 No more available memory(PERM)\nCause:  There is not enough permanent memory. It is impossible to allocate the system variable.\nRemedy:  Please increase the size of S-RAM module. Or, decrease the value of $SGSYSCFG.$M_GUN_NUM.",
    "042": "SVGN-042 Lack of $SGGUN\nCause:  The number of $SGGUN is less than total number of axes in the servo gun group(s).\nRemedy:  Increase $SGSYSCFG.$M_GUN_NUM to the minimum value required to accommodate all servo gun axes. After\nchanging this sysvar, go to control start, and then perform a Cold start, to make the change effective.",
    "043": "SVGN-043 AutoTuning Started.\nCause:  Servo Gun autotuning has been started.\nRemedy:  None. This is a notice to log the event.",
    "044": "SVGN-044 AutoTune Successfully Complete\nCause:  Auto tuning has been completed successfully.\nRemedy:  Cycle controller power in order to use servo gun.",
    "045": "SVGN-045 AutoTuning Failed.\nCause:  Auto Tuning Could not be completed.\nRemedy:  Restart Auto tuning on the tuning menu, and try the operation again.",
    "046": "SVGN-046 FAULTS must be reset.\nCause:  The user executed autotuning while the system was faulted.\nRemedy:  Clear ALL FAULTS and start tuning again.",
    "047": "SVGN-047 Step mode must be disabled.\nCause:  STEP mode is enabled.\nRemedy:  Disable STEP mode, and start tuning again.",
    "048": "SVGN-048 Machine lock must be disabled.\nCause:  Machine Lock is enabled for the servo gun group.\nRemedy:  Disable Machine lock from the TEST CYCLE Menu, and start tuning again.",
    "049": "SVGN-049 Hold must be cleared.\nCause:  Hold is active.\nRemedy:  Clear the HOLD, and start tuning again.",
    "050": "SVGN-050 Autuning: Re-power required\nCause:  Cycling controller power is required to make some parameter changes effective.\nRemedy:  Cycle power before proceeding.",
    "051": "SVGN-051 Backup stroke is not selected.\nCause:  SHIFT + backup (hardkey) was pressed but no Backup Schedule (stroke) was selected.\nRemedy:  Select a backup schedule by pressing the backup hardkey (without the SHIFT key).",
    "052": "SVGN-052 Motion group mismatch.\nCause:  The motion group number of the user program for manual pressure or manual backup is not matched to the Servo Gun\ngroup.\nRemedy:  Change the motion group number of the program to match the Servo Gun.",
    "053": "SVGN-053 Backup stroke is not set.\nCause:  The specified backup schedule (stroke) index is not valid.\nRemedy:  Set a valid backup schedule number.",
    "054": "SVGN-054 $EQNUM is invalid number.\nCause:  $EQNUM is not use in the system.\nRemedy:  Set the valid equipment number to $EQNUM.",
    "055": "SVGN-055 $EQNUM is not Servo Gun.\nCause:  The equipment specified by $EQNUM is not assigned to the Servo Gun.\nRemedy:  Set the equipment number which is assigned to Servo Gun to $EQNUM.",
    "056": "SVGN-056 $GUNNUN is invalid number.\nCause:  Specified number is not valid for $GUNNUM.\nRemedy:  $GUNNUM can be set only 1 or 2 which is corresponding to GUN1 or GUN2.",
    "057": "SVGN-057 Tip Wear Down Cal. is INCOMP.\nCause:  Tip Wear Compensation setup is not complete.\nRemedy:  Perform the Tip Wear Setup procedure. Consult the Servo Gun Manual for details on this procedure.",
    "058": "SVGN-058 UT or UF is different.\nCause:  The tool frame number or user frame number is different from the standard position.\nRemedy:  Change the frame number to same number of standard position.",
    "059": "SVGN-059 Cannot read specified PR[].\nCause:  System cannot read the position register which is specified by $PRINDEX.\nRemedy:  Check the number of $PRINDEX.",
    "060": "SVGN-060 Pressure program is not set.\nCause:  The pressure program name is not set correctly.\nRemedy:  Set correct program name in manual operation setup screen.",
    "061": "SVGN-061 Backup program is not set.\nCause:  The backup program name is not set correctly.\nRemedy:  Set correct program name in manual operation setup screen.",
    "062": "SVGN-062 Pressure data is not selected.\nCause:  The SHIFT + GUN hardkey was pressed, but no Pressure Schedule was selected.\nRemedy:  Select a pressure schedule by pressing the backup hardkey (without the SHIFT key).",
    "063": "SVGN-063 Pressure data is not set.\nCause:  The GUN hardkey was pressed (to select pressure), but no Pressure Schedule was enabled.\nRemedy:  Enable Pressure Schedule(s) for Manual Operation by setting the Manual item to TRUE in the Pressure Schedule data\ntable.",
    "064": "SVGN-064 Manual Weld Verif. Enabled\nCause:  The manual Weld Verification feature was enabled.\nRemedy:  None.",
    "065": "SVGN-065 Manual Weld Verif. Disabled\nCause:  Manual Weld Verification feature was disabled.\nRemedy:  None.",
    "066": "SVGN-066 Manual Weld Verif. Activated\nCause:  The Manual Weld Verification feature was activated.\nRemedy:  None. Just a notification, to let user know he is in this mode and that groups may be disabled automatically.",
    "067": "SVGN-067 Manual Weld Verif. De-Activated\nCause:  The Manual Weld Verification feature was de-activated.\nRemedy:  None. Just a notification to let the user know he is in this mode and that groups may be enabled automatically.",
    "068": "SVGN-068 Could not load program %s\nCause:  The teach pendant program for tip wear measurement could not be loaded. See cause code for reason.\nRemedy:  Resume the program, to re-attempt the load. If the load is successful, then the tip wear measurement will continue.",
    "069": "SVGN-069 Pressure position is near close limit.\nCause:  The actual position of the gun during pressuring (SPOT or PRESS_MOTN) is approaching the guns close limit: the\ndistance between the gun tip (position) and the close limit < $SGSYSCFG.$CLSLMWRNTOL.\nRemedy:  Check the master position and close stroke limit for the gun. If these values are incorrect, then update them. If these\nvalues are correct, then install new tips OR, reduce the value in $SGSYSCFG.$CLSLMWRNTOL (mm) to withhold",
    "070": "SVGN-070 Gun Change is DISABLED.\nCause:  The gun change function is disabled.\nRemedy:  Enable the Gun change function.",
    "071": "SVGN-071 Machine lock is ENABLE.\nCause:  Machine lock for robot axes is enabled at gun attach instruction.\nRemedy:  Release machine lock.",
    "072": "SVGN-072 Illegal assignment of gun axis.\nCause:  Gun number assignment is wrong.\nRemedy:  Confirm Gun number assignment.",
    "073": "SVGN-073 Gun not detatched (AXISORDER).\nCause:  Gun is not detached. Some AXISORDER are not 0.\nRemedy:  GUN ATTACH instruction can be executed only when no gun is attached.",
    "074": "SVGN-074 Gun not detatched.\nCause:  Gun is not detached. Gun attach input signal is OFF.\nRemedy:  GUN ATTACH instruction can be executed only when no gun is attached.",
    "075": "SVGN-075 Gun not attached.\nCause:  Gun is not attached. Gun attach input signal is ON.\nRemedy:  GUN DETACH instruction can be executed only when a gun is attached.",
    "076": "SVGN-076 Another process is executing.\nCause:  Another program is executing GUN ATTACH or GUN DETACH instruction. $CHG_PHASE is not 0 at executing the\ninstruction.\nRemedy:  Wait until another program end GUN ATTACH/DETACH instruction.",
    "077": "SVGN-077 Gun identify signal is OFF.\nCause:  Gun identify signal is OFF.\nRemedy:  Confirm the setting for Gun identify signal.",
    "078": "SVGN-078 Gun set signal is OFF.\nCause:  Gun set signal is OFF.\nRemedy:  Confirm the setting for Gun set signal.",
    "079": "SVGN-079 Gun change canceled.\nCause:  GUN ATTACH or GUN DETACH instruction is canceled while executing the instruction.\nRemedy:  Do COLD START the system.",
    "080": "SVGN-080 Gun change timeout.\nCause:  GUN ATTACH or GUN DETACH instruction become timeout while executing the instruction.\nRemedy:  Do COLD START the system.",
    "081": "SVGN-081 Gun mastering data is lost.\nCause:  Mastering data of the gun is lost by a pause while mastering.\nRemedy:  Do COLD START the system. Then master the gun by manual operation.",
    "082": "SVGN-082 Gun mastering is failed.\nCause:  Gun mastering is failed by a pause while mastering.\nRemedy:  Continue to retry mastering.",
    "083": "SVGN-083 GUN ATTACH is failed (E%d)\nCause:  GUN ATTACH instruction failed. Please see cause code.",
    "084": "SVGN-084 GUN DETACH is failed (E%d)\nCause:  GUN DETACH instruction failed. Please see cause code.\nRemedy:  Please see cause code.",
    "085": "SVGN-085 Robot not mastered(Gun axis).\nCause:  The mastering of servo gun axis has not been performed yet. System variable $master_done set FALSE.\nRemedy:  Please perform the mastering of the servo gun axis.",
    "086": "SVGN-086 Robot not calibrated(Gun axis).\nCause:  The calibration of servo gun axis has not been performed yet. System variable $calibrate set FALSE.\nRemedy:  Please calibrate the servo gun axis.",
    "087": "SVGN-087 Ref pos not set(Gun axis).\nCause:  Reference position has not been set when quick mastering.\nRemedy:  Quick mastering may not be possible. Fixture or zero master.",
    "088": "SVGN-088 Another gun is attached.\nCause:  The gun number specified by the GUN DETACH instruction is different than the currently attached gun.\nRemedy:  Verify the gun number of GUN DETACH instruction.",
    "089": "SVGN-089 Calibrate motion is failed.\nCause:  While the calibrate motion, the detect condition was not triggered.\nRemedy:  Verify the detect condition in the gun change setup screen.",
    "090": "SVGN-090 PR[] index is not set.\nCause:  The PR[] index for the calibrate motion is not set.\nRemedy:  Please set PR[] index for the calibrate motion in the gun change setup screen.",
    "091": "SVGN-091 Touch torque is not set.\nCause:  The Touch torque for the calibrate motion is not set.\nRemedy:  Please set Touch torque for the calibrate motion in the gun change setup screen.",
    "092": "SVGN-092 Detect signal is not set.\nCause:  The Detect signal for the calibrate motion is not set.\nRemedy:  Please set Detect signal for the calibrate motion in the gun change setup screen.",
    "093": "SVGN-093 Gun does not stop.\nCause:  At the Gun Zero Master[] instruction, Servo gun axis does not stop.\nRemedy:  After servo gun axis stops, execute the Gun Zero Master[] instruction.",
    "094": "SVGN-094 GUN EXCHANGE failed (E%d)\nCause:  At the Gun exchange[] instruction, the new gun could not be activated.\nRemedy:  Make sure that the each servogun has valid axisorder.",
    "095": "SVGN-095 Gun type is not opposable.\nCause:  Opposable gun type is required for target gun.\nRemedy:  Set gun type as opposable, if appropriate.",
    "096": "SVGN-096 Gun close is disabled.\nCause:  This operation cannot be performed while Gun Close (stroke enable) is disabled.\nRemedy:  Set the Gun operation to stroke (stroke enable) on the SoftPanel screen. Note: The SoftPanel screen can be accessed\nfrom the TEST CYCLE menu.",
    "097": "SVGN-097 Tip wear down misdetection.\nCause:  The tips did not touch during the 1st step of tip wear measurement due to an increase in gun friction or the tips touched\nbut they are now longer than the reference tips by an amount greater than the Mis-Detect Toler.(mm).",
    "098": "SVGN-098 Invalid inform signal(Gun).\nCause:  The Digital Output assigned for notification of excessive Gun Tip Wear (amount) is invalid.\nRemedy:  Check the present setting of the Inform Signal for the Maximum Wear Check (gun) found on the Tip Wear Detection\nscreen (within the Servo Gun SETUP screen). Change the DO number to one that is configured and unused. Check the\nDigital Output list (I/O-Type-DIGITAL-OUTPUTS) to find an available DO point to use.",
    "099": "SVGN-099 Invalid inform signal(Robot).\nCause:  The Digital Output assigned for the notification of excessive Robot Tip Wear (amount) is invalid.\nRemedy:  Check the present setting of the Inform Signal for the Maximum Wear Check (robot) found on the Tip Wear Detection\nscreen (within the Servo Gun SETUP screen). Change the DO number to one that is configured and unused. Check the\nDigital Output list (I/O-Type-DIGITAL-OUTPUTS) to find an available DO point to use.",
    "100": "SVGN-100 Invalid register number.\nCause:  The specified register number is out of range.\nRemedy:  Set a register index > 0 and < max register number.",
    "101": "SVGN-101 Invalid position reg number.\nCause:  The specified position register number is out of range.\nRemedy:  Set a valid position register number.",
    "102": "SVGN-102 Increased err. not set(Gun).\nCause:  The increased error limit for Gun(movable) tip is set to 0.0mm.\nRemedy:  Set the Increased error to a value greater than 0.0mm if Increased Error checking is needed. This item is set on the Tip\nWear Detection screen (within the Servo Gun SETUP screen).",
    "103": "SVGN-103 Increased err. not set(Robot).\nCause:  Increased error limit for Robot(stationary) tip is set to 0.0mm.\nRemedy:  Set the Increased error to a value greater than 0.0mm if the Increased Error check ing is needed. This item is set on the\nTip Wear Detection screen (within the Servo Gun SETUP screen).",
    "104": "SVGN-104 Excessive load detected.\nCause:  An excessive load is detected, during tip wear setup or tip wear update. The gun zero position might be incorrect.\nRemedy:  Remove any foreign object between the tips, and/or re-master the gun. Resume the tip wear setup or update operation.\nIf the alarm still occurs, then the gun friction has increased since it was last Autotuned. Autotune the gun again and/or\ninspect the gun to determine the cause of the friction increase.",
    "105": "SVGN-105 Failed to reset Pulsecoder.\nCause:  The Pulsecoder alarm was not reset.\nRemedy:  Reset the Pulsecoder alarm again.",
    "106": "SVGN-106 Tip wear uninitialized.\nCause:  Tip Wear Compensation is uninitialized.\nRemedy:  Perform the Tip Wear Setup procedure. Consult the Servo Gun Manual for details on this procedure.",
    "107": "SVGN-107 Tip wear no load threshold.\nCause:  The load threshold used to detect contact with the fixture for the second step of tip wear measurement has not been set.\nRemedy:  Perform the Tip Wear Setup procedure. Consult the Servo Gun Manual for details on this procedure.",
    "108": "SVGN-108 Tip wear no standard pulse.\nCause:  The reference zero position (i.e. standard pulse) used for tip wear measurement has not been set.\nRemedy:  Perform the Tip Wear Setup procedure. Consult the Servo Gun Manual for details on this procedure.",
    "109": "SVGN-109 Tip wear no standard opening.\nCause:  The reference open position (i.e. standard opening) used for the second step of tip wear measurement has not been set.\nRemedy:  Perform the Tip Wear Setup procedure. Consult the Servo Gun Manual for details on this procedure.",
    "110": "SVGN-110 Tip wear no detect DI index.\nCause:  The Tip wear Detection Type is set to DI, but no DI index is specified.\nRemedy:  Confirm that DI detection is the desired type (LOAD detection is the default type). If so, then assign an available DI\npoint to the tip wear detection sensor and set that index value into the Detect Signal item on the Tip Wear Detection\nScreen.",
    "111": "SVGN-111 Failed to touch fixture.\nCause:  The gun tip reached the master position without detecting the fixture (i.e. tip wear plate) during the second step of tip\nwear measurement.\nRemedy:  Confirm that the zero position is correct, then confirm that a rigid fixture is between the tips during the second step of\ntip wear measurement.",
    "112": "SVGN-112 Incomplete Servo tuning.\nCause:  Tip wear measurement or thickness check calibration started, but Servo tuning is incomplete.\nRemedy:  Complete servo auto-tuning. Go to the Gun Setup Utility (UTILITIES-GUN SETUP) and select the Auto Tune item.\nThe Auto Tune program can be started after completing the previous steps in the utility.",
    "113": "SVGN-113 Gun must be open.\nCause:  The tip wear setup or update program started with the gun closed.\nRemedy:  Open the tips, then execute the tip wear measurement program again. If the problem persists, master the gun, then\nexecute the tip wear measurement program again.",
    "114": "SVGN-114 Tip wear misdetection.(FIX).\nCause:  The moving tip did not touch the fixture during the second step of tip wear measurement due to an increase in gun\nfriction, or the fixture and/or robot master position has changed since tip wear was initialized.\nRemedy:  If the moving tip is not pressing into the fixture when the alarm occurs, the fixture touch load (i.e. pressing force) was\nreached without actually touching the fixture. This usually happens because the gun friction has increased since the tip\nwear setup program was run. Increase the Margin of Load item in the Tip Wear Detection Screen to overcome the\nincrease in friction. Doing this can affect the tip wear measurement, so the tip wear setup procedure should be\nperformed again. Autotune the gun again and/or inspect the gun for the cause of the friction increase. If the moving tip\nis pressing into the fixture when the alarm occurs then the fixture position has moved relative to the robot master\nposition, the robot master data has changed, or the points in the program TW_MV2PT.tp have changed. Perform the\ntip wear setup procedure again.",
    "115": "SVGN-115 MP detection failed.\nCause:  Magnet Phase detection failed.\nRemedy:  Retry the operation. Make sure that there is some separation (at least a few mm ), between the guntip/fixedtip and\ndrive mechanism/open_hardstop.",
    "116": "SVGN-116 MP detection unavailable.\nCause:  Magnet Phase detection is unavailable with the current calibration motion type.\nRemedy:  Change the calibration motion type(to 7 or 8) in the Gun change screen.",
    "117": "SVGN-117 Ref pos auto-setup failed.\nCause:  The Gun closing motion to set the reference position failed.\nRemedy:  Confirm that the Touch torque(%) on the Gun SETUP screen is set appropriately.",
    "118": "SVGN-118 Max wear exceeeded (Gun Tip).\nCause:  The maximum tip wear amount has been exceeded on the gun tip.\nRemedy:  Replace the gun tip or re-run tip wear setup.",
    "119": "SVGN-119 Max wear exceeded (Rbt Tip).\nCause:  The maximum tip wear amount has been exceeded on the robot tip.\nRemedy:  Replace the robot tip or re-run tip wear setup.",
    "120": "SVGN-120 Skipped max gun torque update: Gun%d.\nCause:  Max gun torque was not updated due to an invalid parameter.\nRemedy:  See the cause code to identify the reason for the update failure. Correct the problem as described by the remedy for the\nalarm specified in the cause code.",
    "122": "SVGN-122 Pressure is not invertible.\nCause:  The specified pressure cannot be used, it does not lie on the calibration curve (2nd order).\nRemedy:  Change the calibration method to the multi-linear segment method if possible. Do this by setting the system variables\n$sgsyscfg.$cal_model = 12 and $sgsyscfg.$frc2spd_cnv = 3, then perform the pressure calibration again. Alternatively,\nperform pressure calibration again, or reduce max pressure.",
    "123": "SVGN-123 Over-torque protection disabled.\nCause:  Overtorque protection has been disabled.\nRemedy:  This is a warning to notify the operator that overtorque protection is disabled. Enable overtorque protection, if desired.",
    "124": "SVGN-124 Max gun torque must be > floor.\nCause:  The Max Gun Torque parameter in OverTorque Protection is less than the Standard OverTorque Value. The Max Gun\nTorque is the torque required to achieve the Max Pressure of the gun (according to the Pressure Calibration data). The\nStandard OverTorque Value is the lowest torque (i.e. floor) where an abnormal torque condition can be accurately\nobserved due to gun friction.\nRemedy:  To eliminate this alarm either the Max Gun Torque must be increased or the Standard OverTorque Value needs to be\nlower. If OverTorque Protection is still enabled, there might be no action necessary. View the Parameter Summary in\nOverTorque Protection to judge whether the values are acceptable. The Max Gun Torque can be increased by\nincreasing the Max Pressure on the Servo Gun General Setup Screen. If OverTorque Protection is presently disabled,\nbe sure to enable it after this. If the Pressure Calibration is not complete or the data is old, perform the Pressure\nCalibration again.",
    "125": "SVGN-125 Max gun torque must be < ceil.\nCause:  The Max Gun Torque parameter in OverTorque Protection is set higher than the maximum torque of the servo motor.\nRemedy:  Make sure Pressure Calibration of the gun is complete and the data is entered correctly. Perform Pressure Calibration\nagain if possible. Decrease The Max Gun Torque by decreasing the Max Pressure of the gun via the Servogun General\nSETUP Screen.",
    "126": "SVGN-126 Servo parameters exceed max gun torque.\nCause:  Overtorque protection is enabled, but one or more of the parameters responsible for limiting torque exceeded the max\ngun torque.\nRemedy:  Disable, then re-enable overtorque protection, in order to re-write servo parameters. Alternatively, disable overtorque\nprotection OR enable machine lock on the servogun group to disable this alarm.",
    "127": "SVGN-127 DSP max gun torque update timeout.\nCause:  A timeout occurred waiting for acknowledgement of new overtorque parameters.\nRemedy:  Cycle power or toggle the overtorque protect enable. Write the parameters again.",
    "128": "SVGN-128 Invalid thickness value specified.\nCause:  A string parameter or a value less than 0.0 was passed into the THK_VAL macro.\nRemedy:  Re-enter a parameter value greater than or equal to 0.0 into the thickness value macro.",
    "129": "SVGN-129 Invalid thickness tolerance specified.\nCause:  A string parameter or a value less than 0.0 was specified for the THK_TOL macro.\nRemedy:  Re-enter a parameter value greater than or equal to 0.0 into the thickness tolerance macro.",
    "130": "SVGN-130 Invalid thickness severity specified.\nCause:  A string parameter or a value other than 1 or 2 was specified for the THK_SEV (thickness severity) macro.\nRemedy:  Re-enter a parameter value of 1 or 2 into the THK_SEV (thickness severity) macro.",
    "131": "SVGN-131 Invalid gun index specified.\nCause:  A string parameter or a value other than 1, 2, or 3 was specified for gun index in a THK_ macro.\nRemedy:  This parameter is optional but if it is specified, set it as follows: 1: Gun.A only 2: Gun.B only (dual gun case) 3:\nGun.A+B (dual gun case).",
    "133": "SVGN-133 Encoder scale is NULL.\nCause:  An encoder scale value of 0.0 was detected.\nRemedy:  Re-enter the gear ratio on the NOBOT Maintenance menu.",
    "134": "SVGN-134 Thickness Check Calibration Incomplete.\nCause:  Thickness Check Calibration was never performed or did not complete successfully.\nRemedy:  Display the Gun Setup Utility screen (Press MENUS, select UTILITIES, select GUN SETUP) and re-execute the\nThickness Check Calibration.",
    "135": "SVGN-135 Thickness check cal err: bad torque\nCause:  A thickness check calibration point has a torque value that is not greater than 0.0, or is not in ascending order.\nRemedy:  Go to the Gun Setup Utility Screen (UTILITIES-GUN SETUP) and re-execute the Thickness Check Calibration.",
    "136": "SVGN-136 Thickness check cal err: bad deflection\nCause:  A thickness check calibration point has a deflection value that is not greater than 0.0, or is not in ascending order.\nRemedy:  Go to the Gun Setup Utility Screen (UTILITIES-GUN SETUP) and re-execute Thickness Check Calibration. If the\nerror still occurs, re-master and re-execute Thickness Check Calibration.",
    "137": "SVGN-137 Invalid Number of Thickness Cal pts.\nCause:  The number of Thickness Check calibration points is less than 2 or greater than 4.\nRemedy:  Display the system variable screen and enter a value of 2, 3, or 4 into $sgthkset#.$num_cal_pts, where # = gun\nnumber.",
    "138": "SVGN-138 Invalid tipwear ratio.\nCause:  The tip wear ratio for one step wear measurement is invalid (less than 0.0 or greater than 1.0).\nRemedy:  Set the wear ratio in the Tip Wear measurement macro program to a value between 0 and 1. The macro program\nWR_UPDAT is used to perform the Tip Wear measurement with the 1-Step Method. Set the wear-ratio which is found\nas a parameter in a CALL instruction to the program TWKCALC2, or a similar name. Follow the program comments\nto find the proper parameter to adjust: CALL TWKCALC2(wear-ratio,AR[2]).",
    "139": "SVGN-139 Could not read tip stick detect input.\nCause:  Tip stick detect input could not be read, due to an I/O error.\nRemedy:  Check the I/O mapping/configuration and I/O device status.",
    "140": "SVGN-140 Uninitialized start distance number.\nCause:  The specified start distance number is not valid.\nRemedy:  Specify a start distance number greater than or equal to 1 and less than or equal to $sgsyscfg.$dst_elm.",
    "141": "SVGN-141 Uninitialized end distance number.\nCause:  The specified end distance number is not valid.\nRemedy:  Specify an end distance number greater than or equal to 1 and less than or equal to $sgsyscfg.$dst_elm.",
    "142": "SVGN-142 Illegal decel option.\nCause:  The decel rate option setting is incompatible with the speed calibration specification.\nRemedy:  Set $sgsyscfg.$frc2spd_cnv=3 OR contact FANUC for assistance. Note: $sgsyscfg.$frc2spd_cnv==3 is the default\nsetting for this variable, so absolute speed calibration is a non-standard setting.",
    "143": "SVGN-143 Stoperlim:%.1fmm < PushDepth:%.1fmm.\nCause:  Automaster operation is executing and position error due to push depth exceeds stoperlim. Stop error excess alarm\nmay occur.\nRemedy: Increase $SGGUN#.$SETUP.$STOPERL IM or decrease pushing depth.",
    "144": "SVGN-144 Min press speed < 1mm/sec.\nCause:  The Minimum speed must be greater than 1mm/sec.\nRemedy:  Re-perform force calibration to update $sggun#.$setup.$prs_spd_min automatically AND/OR manually set\n$sggun#.$setup.$prs_spd_min to a valid value.",
    "146": "SVGN-146 Joint velocity limit too low.\nCause:  The joint velocity limit must be greater than zero, for mm/sec pressure calibration speed specification.\nRemedy:  Update the joint velocity limit using one of the following methods:\n1.  Re-enter the gear ratio via the Servo Gun Axes item on the Maintenance menu, at Control start.\n2.  Directly enter the Max Joint Speed on the Axis Data screen of the Servo Gun Setup menu, at control start.",
    "147": "SVGN-147 Sync/speed min distance =%s.\nCause:  The minimum gun opening distance required to achieve the specified contact speed for this Pressure Schedule is larger\nthan the opening specified by the Start Distance schedule used in the SPOT or Press_Motion instruction. The correct\ncontact speed might not have been achieved during execution of this instruction.\nRemedy:  Increase the Start Distances assigned to the Distance Schedule that is used when this alarm occurs. Go to the Distance\nSchedule data table (DATA-DISTANCE) and increase the gun and/or robot distances.",
    "148": "SVGN-148 Cant identify routine name.\nCause:  The routine name corresponding to the standalone instruction cannot be identified. Refer to the cause code for the root\ncause.\nRemedy:  See remedy for cause error.",
    "149": "SVGN-149 CP enable is required.\nCause:  CP mode is not enabled, but synchronize move to pressure position is enabled AND/OR linear distance is enabled.\nRemedy:  Enable CP mode (set $cpcfg.$cp_enable=TRUE) or contact FANUC for assistance.",
    "150": "SVGN-150 Synchronization enable is required.\nCause:  The linear distance function is enabled, but synchronize move to pressure is not enabled.\nRemedy:  Enable synchronize move to pressure position (set $sgsyscfg.$sync_mv2prs=TRUE) OR disable linear distance (set\n$sgsyscfg.$lin_dst_enb=FALSE).",
    "151": "SVGN-151 Cannot add file to backup/restore list.\nCause:  The Servogun sysvar file(s) could not be added to the backup/restore list.\nRemedy:  Document the events that led to the error and call your FANUC technical representative.",
    "152": "SVGN-152 Invalid increase signal(Gun).\nCause:  The Digital Output assigned to notify of increased error on the Gun Tip is invalid.\nRemedy:  Check the present value of $sggun#.$setup.$tipincioidx (on the system variable screen). Change this value to the\nnumber of a DO that is configured and unused. Check the Digital Output list (I/O-Type-DIGITAL-OUTPUTS) to find\nan available DO point to use.",
    "153": "SVGN-153 Invalid increase signal(Robot).\nCause:  The Digital Output assigned to notify of increased error on the Robot Tip is invalid.\nRemedy:  Check the present value of $sggun#.$setup.$rbtincioidx (on the system variable screen). Change this value to the\nnumber of a DO that is configured and unused. Check the Digital Output list (I/O-Type-DIGITAL-OUTPUTS) to find\nan available DO point to use.",
    "158": "SVGN-158  PAUSE.G    Thk%s,Push(Exp%s,Aval%s,Max%s)mm.\nCause:  This alarm provides information to identify the root cause of the pressure shortage alarm.\nParameters meanings are:\nThk: Thickness expected (value specified in pressure schedule)\nPush.Exp: Pushing depth expected (larger of pushing depth in pressure schedule and speed depth)\nPush.Aval: Pushing depth available (thk + current close stroke limit)\nPush.Max: Pushing depth maximum (thk + standard close stroke limit)\nRemedy:  If thickness and/or pushing depth are incorrect, then adjust them.\nIf stroke limit has become too small, install new tips.",
    "159": "SVGN-159  PAUSE.G    Pressure margin conversion error.\nCause:  Pressure margin conversion for touchup process failed.\nSee cause code for reason.\nRemedy:  Refer to cause codes remedy.",
    "160": "SVGN-160 Invalid calibration point: bad torque.\nCause:  A pressure calibration point has a torque value that is not greater than 0.0, or is not in ascending order.\nRemedy:  Perform Pressure Calibration again. Make sure that both torque and pressure increase at each successive calibration\npoint.",
    "161": "SVGN-161 Invalid calibration point: bad speed.\nCause:  A Speed value in the Pressure Calibration table is less than the min speed or greater than the max speed.\nRemedy:  Perform Pressure Calibration again. Make sure that the Speed for each point in the Pressure Calibration table is within\nthe operating range of the gun.",
    "162": "SVGN-162 Invalid calibration point: bad pressure.\nCause:  A pressure calibration point has a pressure (force) value that is not greater than 0.0, or is not in ascending order.\nRemedy:  Perform Pressure Calibration again. Make sure that both torque and pressure increase, at each successive calibration\npoint.",
    "163": "SVGN-163 Invalid calibration model setting.\nCause:  The calibration model setting ($sgsyscfg.$cal_model) is not supported. The following settings are supported: 3: Single\nlinear segment pressure and speed model 12: Multiple linear segment pressure and speed model piece-wise pressure\ncalibration.\nRemedy:  Change setting to one of the settings above, and reperform calibration if necessary.",
    "164": "SVGN-164 Invalid pressure/speed convert setting.\nCause:  Pressure to speed conversion specification ($sgsyscfg.$frc2spd_cnv) is not supported. The following setting\ncombinations are supported: $sgsyscfg.$cal_model = 3 and $sgsyscfg.$frc2spd_cnv = 0: Single linear segment, JNT%.\n$sgsyscfg.$cal_model = 3 and $sgsyscfg.$frc2spd_cnv = 3, Single linear segment, mm/sec converted at spot.\n$sgsyscfg.$cal_model = 12 and $sgsyscfg.$frc2spd_cnv = 3, Multiple linear segments, mm/sec converted at spot.\nRemedy:  Change setting to one of the settings above, and re-perform calibration if necessary. Note: $sgsyscfg.$frc2spd_cnv==3\nis the default setting for this variable.",
    "165": "SVGN-165 Gun opened < equalizer trigger distance.\nCause:  The open distance condition for equalization pressure trigger, was not met before the start of motion to pressure\nposition, for the next spot. The equalization trigger state for the next spot might have been delayed, in this case.\nRemedy:  Increase the end and/or start distance value on the distance schedule screen, or decrease the open distance for the\nequalization pressure trigger AFTER the SPOT.",
    "166": "SVGN-166 Invalid equalizer trigger type.\nCause:  The specified equalization pressure trigger type is not supported.\nRemedy:  Select a valid trigger on the Spot equipment SETUP screen.",
    "167": "SVGN-167 Invalid equalizer trigger event.\nCause:  The specified equalization pressure trigger event is undefined.\nRemedy:  Go to the Spot Equipment SETUP screen, and select a valid trigger event.",
    "168": "SVGN-168 Push depth %s[mm] exceeds strokelimit\nCause:  The pushing depth specified in the pressure schedule or the minimum pushing depth, exceed the stroke limit. The\ncontact speed might be slightly lower than specified as a result of this alarm.\nRemedy:  Update one or more of the parameters used to specify pushing depth: $sgsch#[].$push_depth and\n$sggun.$setup.$push_margin. If these parameters cannot be reduced, then increase the stroke limit, if possible. Note\nthat this is only a warning.",
    "169": "SVGN-169 PushDepth%s[mm]clampd, speed affected\nCause:  The minimum push depth (internally calculated distance) required to decelerate from the contact speed exceeds the\nmaximum possible pushing depth: part thickness + close stroke limit. The value of the minimum pushing depth\n(specified in the alarm message) was clamped to the maximum possible pushing depth.\nRemedy:  Decrease $sggun#.$setup.$push_margin, or increase the close stroke limit. Although this alarm has a warn severity,\nthis condition should be corrected since the minimum push depth has been clamped to a value that is small enough to\naffect contact speed and/or contact speed persistence. Note 1: SVGN-169, basically indicates that the close limit value\nis abnormal, since minimum push depth is typically less than 5mm. Note 2: part thickness is automatically added to the\npushing depth value during tryout mode to compensate for the missing part.",
    "170": "SVGN-170 Incompatible PRESS_MOTN format.\nCause:  The instruction format PRESS_MOTN[SD=,P=,SEL=(,)] cannot be used with the setting\n$SGSYSDG.$UGA_IDX4GB=FALSE. GunB must use GunA data, for this instruction.\nRemedy:  If you want to use the instruction format PRESS_MOTN[SD=,P=,SEL=(,)] then set\n$SGSYSDG.$UGA_IDX4GB=TRUE. If you do not want to use the instruction format\nPRESS_MOTN[SD=,P=,SEL=(,)] then change the instruction to PRESS_MOTN[SD=(,),P=(,)] ( the setting of\n$SGSYSDG.$UGA_IDX4GB is ignored for the format PRESS_MOTN[SD=(,),P=(,)] ).",
    "171": "SVGN-171 Requested torque > max gun torque.\nCause:  The Pressure[]kgf or Pressure level Gun instruction was executed, and the requested torque > max gun torque (OTP\ntorque limit mode).\nRemedy:  Perform autotuning or disable overtorque protection.",
    "172": "SVGN-172 Can not move gun during interrupt\nCause:  A SPOT[] or PRESS_MOTN[] instruction was performed during an interrupt routine (Ex. TB,TA,DB,program monitor\netc).\nRemedy:  Adjust the trigger timing of interrupt routine. Also, wait until the interrupt routine completes then run the servo gun\ninstruction",
    "173": "SVGN-173 Timeout G%d A%d %x %d\nCause:  A timeout occurred during Gun-attach or -detach at the start.\nThe causes are as follows.\n1. Other alarms might occur at the start.\n2. The servo gun is NOT connected correctly. For example Pulsecoder cable disconnection and defective amplifier.\nRemedy:  At first, confirm other alarms that occurred at the same time and remove cause of them.\nHere is an example of alarms.\nSRVO-058 FSSB %d init error (%d)\nIf this problem persists after taking the above action, check the connections of cables for servo gun.",
    "174": "SVGN-174 SPCALL error fcod:%x, stat:%x\nCause:  An internal error has occurred.\nRemedy:  Document the events that led to the error and call your FANUC technical representative.",
    "175": "SVGN-175 Position not recorded\nCause:  GunTouchup(F3) or AutoTouchup(F4) was requested but touchup did not occur.\nThis alarm (SVGN-175) only indicates that touchup failure has occurred, SVGN-176 identifies cause of SVGN-175.\nNote: SVGN-175 is not posted during program touchup.\nRemedy:  See SVGN-176. NOTE: SVGN-175 is an optional alarm (enabled by default).\nSet $SGSYSTCH.$PTNOTRECALM  = FALSE to disable SVGN-175.",
    "176": "SVGN-176 %s\nCause:  Refer to message in string.\nRemedy:  Refer to remedy for message in string.",
    "177": "SVGN-177 Thk%smm,CloseLim%smm,StdLim%smm\nCause:  This is information at pressure shortage.\nRemedy:  Incorrect thickness or/and gun close limit would cause a pressure shortage If thickness or/and gun close limit is\nincorrect, gun tip can not go correct push depth for setpoint pressure The Thk is value which is specifiied in pressure",
    "178": "SVGN-178 Open/CloseLim=%s\nCause:  This is information of standard stroke limit.\nRemedy:  Gun stroke limit is compensated by tip wear down. The standard value is stroke limit when TW_SETUP or\nWR_SETUP is performed an original value. This shorter standard stroke limit may cause pressure shortage. If the\nstandard stroke limit is shorter than original value, set correct standard limit in servo gun setup screen.",
    "179": "SVGN-179 More than two groups\nCause:  The program attempted the servogun command with more than 2 groups.\nRemedy:  The servogun option supports a maximum of 2 groups due to complex synchronization. Use a program with less than 3\ngroups in the group mask, or remove servogun command (SPOT or PRESS_MOTN) from the program.",
    "180": "SVGN-180 Pressure persist is canceled\nCause:  Persisted pressure after HOLD is canceled.\nRemedy:  Pressure could not be persisted during BWD or ABORT So Persisted pressure is canceled This is warning massage for\nblowing out. Please check panel status if you are welding.",
    "181": "SVGN-181 Nominal thickness:%s MinAllowable:%s\nCause:  The Measured part thickness is less than the under-thickness limit(mm). The part may be out-of-tolerance. NOTE:\nThis message displays the nominal (expected/programmed) thickness and the under-thickness (MinAllowable) limit.\nRemedy:  See SVGN-040.",
    "182": "SVGN-182 Nominal thickness:%s MaxAllowable:%s\nCause:  The Measured part thickness is greater than the over-thickness limit(mm). The part may be out-of-tolerance. NOTE:\nThis message displays the nominal (expected/programmed) thickness and the over-thickness (MaxAllowable) limit.\nRemedy:  See SVGN-040.",
    "183": "SVGN-183 %s,%s,%s,%s\nCause:  Gun touchup function has modified position of spot point.\nThis message is provided for informational purposes only, it is not a fault/problem.\nNote: SVGN-183 is not posted during program touchup.\nRemedy:  The 4 parameters in SVGN-183 p1/p2/p3/ p4 provide details about the modified point.\np3: Corrected value is the difference between new recorded position and old recorded position.\nNote: robot close direction is positive polarity, so if new position is shifted in robot open direction (relative to old\nposition) corrected value will be negative.\np4: Thickness value is actual thickness measured during thickness check.\nNote: If thickness check is disabled, nominal thickness (value in pressure schedule) is reported.",
    "184": "SVGN-184 Point touchup cancelled.\nCause:  Spot point touchup was cancelled, because shift key was released and program edit screen was de-selected (new screen\nwas selected).\nRemedy:  Execute point touchup again, and dont exit editor screen.",
    "185": "SVGN-185 Gun monitor buffer overflow\nCause:  Data collected during search process exceeded storage buffer. Note: SVGN-185 only occurs during unpress (a process\nthat is no longer used), so it is basically obsolete.\nRemedy:  Reduce unpress time by increasing speed ($SGGUN#.$TEACH.$LWDT_CLOSPD) or decreasing observation time\n($SGGUN#.$TEACH.$LWDT_OBSLEN).",
    "186": "SVGN-186 Wdn:%smm->%smm\nCause:  This indicates information for tip increased error. The left value indicates the last wear down. The right value indicates\ncurrent measured wear down. Since the current measured wear down is incorrect, so increased alarm is posted.\nDifference of the right value from the left value becomes increased error amount.",
    "187": "SVGN-187 Do gun zero mastering with new tip\nCause:  Tip wear setup was performed, without performing gun zero mastering.\nThe cause are as follows.\n1. Tip wear setup might be performed with a worn tip.\n2. Tip wear setup might be performed again after tip wear update was performed.\nRemedy:  Confirm that new tip is worn and perform gun zero mastering.\nThen perform tip wear setup.",
    "188": "SVGN-188 Restart info incomplete:%d/%d/%d\nCause:  An internal error has occurred. Execution restart information is incomplete.\nRemedy:  Document the events that led to the error and call your FANUC technical representative.",
    "189": "SVGN-189 Tipwear overstroke protection is off\nCause:  Tipwear had been setup, but a BZAL alarm occurred and tipwear zero reference (pls0) is not up to date. Pls0 must be\nupdated after BZAL to maintain proper stroke limit (Overstroke protection is turned of after BZAL to avoid invalid\nstrokelimit values).\nRemedy:  Go to gun master screen and execute recalibrate or master. Either action updates pls0, and turns overstroke protection\non.",
    "190": "SVGN-190 Backup before search clamped:%smm\nCause:  Open (search start) distance for upper panel detection exceeded gun stroke limit, so open distance was clamped to gun\nopen limit.\nNote: Gun open distance for upper panel search depends on touchup type:\nif point touchup:\nopen distance = initial pos + search prep dist\nif prog touchup:\nopen distance = thk.nom + thk.err.max + pos.err.max + search prep dist\nSVGN-190 does not cause any problem if panel contact occurs AFTER search start. However, if panel contact occurs\nBEFORE search start, excessive push and/or touchup failure may result.\nRemedy:  If point touchup is being performed, close gun (jog) to reduce open distance. If program touchup is being performed,\nreduce one or more of the following parameters: upper panel detect distance, max thickness error, max pos error.",
    "191": "SVGN-191 Thickness Check Calib Updated.\nCause:  Thickness Check Calibration was successful - parameters were updated.\nNote: This alarm is merely status information, it is not a fault/problem.\nRemedy:  None.This is a massage.",
    "192": "SVGN-192 Thickness Check Calib Not Updated.\nCause:  Thickness Check Calibration parameters were not updated, thickness Check Calibration failed.\nNote: If thickness Check Calibration had been done prior to present calibration attempt, the last parameter were\nrestored.\nRemedy:  Please see cause code and other relevant alarms in alarm log. Correct issue that caused that calibration to pause/fail\nand retry Thickness Check Calib.",
    "193": "SVGN-193 Automastered:%.1fmm from old masterpos.\nCause:  Automaster operation was successful, and mm distance between old and new master position is provided for reference.\nRemedy:  No remedy needed - this alarm is for information purposes only.",
    "194": "SVGN-194 Automaster failed.\nCause:  Automaster operation failed. Refer to cause code for reason.\nRemedy:  Formulate remedy based on cause code.",
    "195": "SVGN-195 Masterct(old:%d,new:%d).\nCause:  Automaster operation was successful, and master count values - old and new - are provided for reference.\nRemedy:  No remedy needed - this alarm is for information purposes only.",
    "196": "SVGN-196 TW recalibrated:%.1fmm from old pulse0.\nCause:  Auto wear calibrate operation was successful, and mm distance between old and new pulse0 value is provided for\nreference.\nRemedy:  No remedy needed - this alarm is for information purposes only.",
    "197": "SVGN-197 TW recalibrate failed.\nCause:  Auto wear calibrate operation failed. Refer to cause code for reason.\nRemedy:  No remedy needed - this alarm is for information purposes only.",
    "198": "SVGN-198 Pulse0ct(old:%d,new:%d).\nCause:  Auto wear calibrate operation was successful, and master count values - old and new - are provided for reference.\nRemedy:  Refer to cause code for specific information.",
    "199": "SVGN-199 Automaster message.\nCause:  Status information about automaster operation is being posted.\nRemedy:  Refer to cause code for specific information.",
    "200": "SVGN-200 FCTRL must be off for automaster.\nCause:  Automaster was requested while gun was still in force control. Automaster cannot start until fctrl is cleared.\nRemedy:  Press fault reset and execute automaster again. (SVGN-200 alarm automatically resets force control).",
    "201": "SVGN-201 Gun index 1\nCause:  The posted error occurred on GunA (gun index 1) of the dual gun.\nRemedy:  Correct the error on the gun number corresponding to GunA (gun index 1).",
    "202": "SVGN-202 Gun index 2\nCause:  The posted error occurred on GunB (gun index 2) of the dual gun.\nRemedy:  Correct the error on the gun number corresponding to GunB (gun index 2).",
    "203": "SVGN-203 GunA, GunB contact speed is different\nCause:  The contact speed used in this Pressure Schedule is different for Gun A and Gun B - but contact speed must match to\nachieve synchronized contact with the part.\nRemedy:  Set the contact speed of the Pressure Schedule to the same value for both guns. This is done by adjusting the pressure\ncalibration data which determines the contact speed. The Speed at a given Pressure must be the same for both guns. It\nis recommended to use matching Pressure and Speed values for each calibration point for both guns. Then, find the\nunique torque% required to achieve the pressure for each gun. OR, just set the contact speed for all points in the\nPressure Calibration table for both guns to the same value.",
    "204": "SVGN-204 GunA, GunB pushing depth is different\nCause:  Pushing depth is different for GunA and GunB. Equal pushing depth is required, for synchronized move to pressure\nposition.\nRemedy:  Set $sgsch#[].$pushing depth, and $sggun#.$setup.$push_margin to same value, for both guns.",
    "205": "SVGN-205 GunA, GunB creep distance is different\nCause:  The creep distances are different for GunA and GunB. Equal creep distance is required to achieve synchronized\ncontact with the part.\nRemedy:  Set the system variable $sggun#.$setup.$creep_dst to the same value, for both guns on this dual-gun (# represents the\ngun number).",
    "206": "SVGN-206 GunA, GunB part thickness is different\nCause:  The Part Thickness used in this Pressure Schedule is different for GunA and GunB. Equal thickness is required to\nachieve synchronized contact with the part.\nRemedy:  Set the part thickness to same value, for both guns.",
    "209": "SVGN-209 GunA, GunB joint velocity limits differ.\nCause:  Joint velocity limits are different for gunA and gunB. The joint velocity limits must be equal to achieve synchronized\ncontact with the part.",
    "210": "SVGN-210 GunA, GunB accel times differ\nCause:  Acceleration Times are different for gunA and gunB. The acceleration times must be equal to achieve synchronized\ncontact with the part.\nRemedy:  Use the Gun Setup Utility to set the Acceleration Times of both Gun A&B to the same value. Perform the following:\n1. Press MENU.\n2. Select UTILITIES.\n3.  Select GUN SETUP.\n4.  Press F6, DG_CHECK.\n5.  Press F5, SETACC and reply YES to the prompt to set the accel time to the same value.\n6.  Cycle Power to activate the change.",
    "211": "SVGN-211 Incomp weight calc in ATUN\nCause:  Weight calculation in the autotuning is not completed. Therefore, pressure was not able to be compensated.\nRemedy:  Complete weight calculation of the autotuning screen.",
    "212": "SVGN-212 Incomp weight calc for X gun\nCause:  Weight calculation for X gun is not completed. Therefore, pressure was not able to be compensated.\nRemedy:  Complete weight calculation by executing WT_MEAS.TP.",
    "213": "SVGN-213 Cant detect pressure posture\nCause:  The pressurizing posture cannot be detected.\nRemedy:  The setting of the tool coordinate system is wrong. It is necessary to set the tool coordinate system to the servo gun\ntips of fixed side. Moreover, +Z tool coordinate axial direction should be the same as the gun open direction.",
    "214": "SVGN-214 Servo gun type is not set\nCause:  Servo gun type is not set. Therefore, pressure was not able to be compensated.\nRemedy:  Confirm the weight compensation gun type of the Servo Gun General Setup screen.",
    "215": "SVGN-215 Incomp manual wt comp setup\nCause:  Incomplete manual weight compensation setup was performed. Therefore, pressure was not able to be compensated.\nRemedy:  Go to the Servo Gun General Setup screen, select Manual weight compen. Complete compensation formula.",
    "216": "SVGN-216 Illegal wt compens val: Gun%d,P%d\nCause:  The weight compensation value is too large. Therefore, pressure was not able to be compensated.\nRemedy:  Confirm the contents of the setup of the weight compensation function.",
    "217": "SVGN-217 Do press calib over again\nCause:  There is mistake in the setting of weight compensation function at pressure calibration.\nRemedy:  Confirm the weight compensation gun type of the Servo Gun General Setup screen Confirm the setting of tool\ncoordinate system Execute pressure calibration again.",
    "218": "SVGN-218 This press cant be compensated\nCause:  Because this command pressure was lower than the value of WT compensation press low lim of Servo Gun General\nSetup screen, this command pressure was not able to be compensated.\nRemedy:  Confirm the value of WT compn press low lim of the Servo Gun General Setup screen.",
    "219": "SVGN-219 Angle is wrong\nCause:  A set value of the angle is wrong.",
    "220": "SVGN-220 Set value is wrong\nCause:  A set value is wrong. The calculated weight has become negative.\nRemedy:  The interval between angle and angle at pressure calibration should be away by 70 degrees or more. Confirm the set\nvalue of the angle. The pressure or the command pressure might be wrong. Confirm the set values of the pressure and\nthe command pressure.",
    "221": "SVGN-221 Incomp semi-auto wt comp setup\nCause:  Incomplete semi-auto weight compensation setup has occurred. Therefore, the pressure was not able to be\ncompensated.\nRemedy:  Go to the Servo Gun General Setup screen, and select the Semi-auto weight compensation. Complete semi-auto weight\ncompensation setup.",
    "222": "SVGN-222 UT correct ang is out of range\nCause:  The UT correct angle is out of range. Therefore, the position of the gun was not able to be calculated.\nRemedy:  Go to the Servo Gun General Setup screen. Set up the WT compen UT correct angle between 0 and 360.",
    "223": "SVGN-223 Max disturbance excess G%d\nCause:  Max disturbance torque exceeds the tolerance.\nRemedy:  Check the pressure calibration.",
    "224": "SVGN-224 Average disturbance excess G%d\nCause:  Average disturbance torque exceeds the tolerance.\nRemedy:  Check the pressure calibration.",
    "225": "SVGN-225 Min disturbance excess G%d\nCause:  Min disturbance torque exceeds the tolerance.\nRemedy:  Check the pressure calibration.",
    "226": "SVGN-226 Servogun Diagnosis is failed.\nCause:  Servogun diagnosis is failed.\nRemedy:  Internal error.",
    "230": "SVGN-230 Manual weight setup err: Gun%d,P%d\nCause:  A mistake is found in the setting of the manual weight compensation. Therefore, pressure was not able to be\ncompensated.\nRemedy:  Go to the Servo Gun General Setup screen, select Manual weight compen. Confirm the setting of the manual weight\ncompensation function.",
    "231": "SVGN-231 Cant detect pressure posture\nCause:  Pressurizing posture cannot be detected.\nRemedy:  The setting of the tool coordinate system is wrong. It is necessary to set the tool coordinate system to the servo gun\ntips of fixed side. Moreover, +Z tool coordinate axial direction should be the same as the gun open direction.",
    "232": "SVGN-232 This gun cannot use AUTO\nCause:  This gun cannot use the auto weight compensation type.\nRemedy:  Set the gun to another weight compensation type.",
    "233": "SVGN-233 This gun cannot use AUTO\nCause:  This gun cannot use the auto weight compensation type.\nRemedy:  Set the gun to another weight compensation type.",
    "234": "SVGN-234 Recorded touchup log.\nCause:  This message is posted if user presses F2(rec) fkey when prompt \"Is tip on panel\" is presented.\nSVGN-234 is merely a status message, it is not a problem.",
    "235": "SVGN-235 Already Recorded touchup log.\nCause:  User notification that touchup log already exists. This message is posted if F2(rec) fkey is pressed more than once,\nwhen tip on panel prompt is presented.\nRemedy:  Press F2(rec) fkey only once.",
    "236": "SVGN-236 [PauseMod]Det/Thk/Pos Err :Eq%d\nCause:   Program execution paused because position and/or thickness is out of tolerance. This pause occurs when\nDET/THK/POS error pause severity is set to warn or alarm and one more of the following conditions exist:\n. SVGN-237 Position error:(Eq:%d,Ln:%d)\n. SVGN-239 Thickness error:(Eq:%d,Ln:%d)\n. SVGN-240 Up Panel Mis-Detect:(Eq:%d,Ln:%d)\n. SVGN-252 Panel detection was failed:(Eq:%d,Ln:%d)\n. SVGN-254 Low Panel Mis-detect:(Eq:%d,Ln:%d)\n. SVGN-260 Search motion is unsuccess.\nRemedy:   Set Det/Thk/Pos error pause Sev in the gun teach setup screen to DISABLE if you do not want robot to pause when the\nalarms above occur.",
    "237": "SVGN-237 Excessive position error:(Eq:%s)\nCause:  Measured position error is greater than maximum allowable position error or less than min allowable position error.\"\nRemedy:   Take the following actions.\n1.  Confirm the tip wear amount is correct. Re-execute the tip wear measurement when the tip wear amount is not\ncorrect.\nNote: if you take above action, re-execute the thickness check calibration.\nIf this problem persists after taking the above actions, confirm that:\n1.  Max allowable Pos error (on gun teach setup screen) is large enough.\n2.  Min allowable Pos error (on gun teach setup screen) is small enough.\nIf not, measured position error is made greater than min allowable position error and less than maximum allowable\nposition error in the following ways.\n1.  Touch up correct position using jog or point touchup(not program touchup).\n2.  Increase maximum allowable position error or decrease min allowable position error on gun teach setup screen.\nNote: if    initial position error is too large, program touchup cannot touch up. Fanuc recommends using point\ntouchup(not program touchup) at the initial touchup.\nIf this problem still persists after taking the above actions, take the following actions.\n1.  Confirm the position error offset in the spot program touchup setup screen. This alarm might be generated\nimmediately after the position error offset is changed.\n2.  Confirm the parameter to correct position for Xgun in the spot program touchup setup screen. This alarm might\nbe generated immediately after the parameter to correct position for Xgun is changed.\nIf this problem persists after taking the all actions, perform the following actions:\n1.  Acquire the diagnostic data. See the procedure for diagnostic data collection at Troubleshooting section.\n2.  Contact a FANUC technical representative.",
    "238": "SVGN-238 [PauseMod]SpotProgTouchDsb:Eq%d\nCause:  Program execution paused because TCHDSB is attached to spot instruction, and SpotprogTouch_DSB pause severity\n= warn or alarm.\nRemedy:  If you do not want robot to pause, either:\na. set SpotProgTouch_Dsb pause Sev in the gun teach setup screen to DISABLE OR\nb. remove TCH_DSB from spot instruction.",
    "239": "SVGN-239 Thickness error:(Eq:%d,Ln:%d)\nCause:  Measured thickness is out of tolerance. Note: SVGN-242 Act thick:x.x, Nom thick: y.y is posted as cause code for\nSVGN-239.\nRemedy:  Confirm that:\n1. actual panel thickness is correct.\n2. nominal thickness in the pressure schedule is correct.\n3. OverThickness and UnderThickness tolerance values on gun teach setup screen are appropriate.",
    "240": "SVGN-240 Up Panel Mis-detect:(Eq:%d,Ln:%d)\nCause:  Upper panel detection distance is larger (gun more open) than max detect distance. where: max detect distance =\npos.err.max + thk.nom + thk.err.max. This alarm occurs only during program touchup (not point touchup).\nNote: SVGN-243 ActDetDist:x.x, MaxDetDist: y.y is posted as cause code for SVGN-240.\nRemedy:   Confirm that:\n1.  no obstruction exists between guntip and panel.\n2.  ensure that panel is present on correct position.\n3.  the master position for the gun axis is correct and the tips touch at the zero.\n4.  the tip wear amount is correct. Re-execute the tip wear measurement when the tip wear amount is not correct.\nIf the above item is OK, confirm that:\n1.  nominal thickness in pressure schedule is correct.\n2.  OverThickness tolerance (on gun teach setup screen) is large enough.\nIf the above items are OK, confirm that:\n1.  Max allowable Pos error (on gun teach setup screen) is large enough.\nIf the above item is NG, the position error is made less than maximum allowable position error in the following ways.\n1.  Touch up correct position using jog or point touchup(not program touchup).\n2.  Increase maximum allowable position error on gun teach setup screen.\nNote: if    initial position error is too large, program touchup cannot touch up. Fanuc recommends using point\ntouchup(not program touchup) at the initial touchup.",
    "241": "SVGN-241 ActPosErr:%smm > MaxPosErr:%smm\nCause:  Position error exceeds Max allowable pos error. SVGN-241 supplies the actual position error and maximum allowable\nposition error for alarm SVGN-237.\nRemedy:  See SVGN-237.",
    "242": "SVGN-242 Act thick:%smm Nom thick:%smm\nCause:  Thickness error exceeds OverThickness tolerance or UnderThickness tolerance. SVGN-242 supplies the actual\nthickness and nominal thickness for SVGN-239.\nRemedy:  See SVGN-239.",
    "243": "SVGN-243 ActDetDis:%smm MaxDetDis:%smm\nCause:  Detect distance (observed) exceeds Max Detect distance. SVGN-243 supplies the actual detection distance and max\ndetect distance for SVGN-240.\nRemedy:  See SVGN-240.",
    "244": "SVGN-244 Retry Thickness Check calibration\nCause:  Thickness check calibration (0kgf)is incomplete. Thickness check calibration is required for touchup.\nRemedy:  Execute thickness check calibration on gun setup util.",
    "245": "SVGN-245 Gun not open to undeflect pos\nCause:  Position register (PR) that stores undeflect (relax) position for gun/robot could not be set.    Note that undeflect pos is\nstarting point for thickess check, it removes deflection at lower panel detect end. Note that Refer to cause code for\nspecific reason.\nRemedy:  Correct problem identified in cause code, and retry touchup.",
    "246": "SVGN-246 Machinelock required for PNLSIM.\nCause:  Panel simulation is enabled, but machinelock is disabled on robot group or gun group. Machinelock must be\nENABLED on both robot group and gun group, when panel simulation is enabled.\nRemedy:  Disable panel simulation($SGSYSTCH.$SIM_PNL_ENB=FALSE) or ENABLE machinelock on robot group and gun\ngroup.",
    "247": "SVGN-247 Concurrent multiarm touchup unsupported.\nCause:  Touchup is already in progress on an arm and touchup is being requested on another arm (at the same time). Touchup\ncan only be performed on one arm at a time.\nRemedy:  Wait for touchup operation that is already in progress to complete, before starting touchup on another arm.",
    "248": "SVGN-248 Panel not detected.\nCause:  Upper or lower panel search ended, but panel was not detected. I.E. gun speed never fell below speed threshold, during\nsearch. The following conditions can cause this problem:\n1. missing panel\n2. large gun friction\n3. large pressure margin\nRemedy:  1. ensure that panel is present.\n2. increase $sggun#.$teach.$pnldflctdst.\n3. decrease pressure margin.\nIf problem persists, contact a FANUC technical representative.",
    "249": "SVGN-249 Panel Detection was failed.\nCause:  Panel was not detected during second part of upper panel search. Internal condition for search termination was not met.\nThis can occur if panel is soft.\nRemedy:  Retry touchup.",
    "250": "SVGN-250 Spot program touchup enabled !\nCause:  A tp program started (or resumed) and spot program touchup function is enabled with execution mode = TOUCHUP.\nTouchup mode means that points will be evaluated AND positions will be modified.\nRemedy:  If verify (not touchup) mode is desired, change execution mode via Touchup setup screen:\na. if tp is disabled, set Execution mode for AUTO = VERIFY mode,\nb. if tp is enabled, set Execution mode for TEACH = VERIFY mode,\nIf normal spot (not touchup or verify) operation is desired, disable program touchup via:\na. DIN, if tp is disabled.\nb. Touchup mode setup screen, if tp is enabled.",
    "251": "SVGN-251 ActPosErr:%smm < MinPosErr:%smm\nCause:  Position error (change between observed position and recorded position) is less than MinPosError. This message is\nposted to display magnitude of observed position error and minimum pos error, when SVGN-237 occurs. Note that\nmin pos error is used in conjunction with max pos error to control when points are touched up. Points are only touched\nup if position error is >= min pos error and <= max pos error. Min pos error tolerance identifies when position change\nis small and/or insignificant.\nRemedy:  If position error is acceptable, decrease min pos error and execute touchup again. Set min pos error = 0.0, to disable\nmin pos error check completely.",
    "252": "SVGN-252 Panel Detection failed.(%d)\nCause:   Upper panel detection failed. The integer parameter ()identifies the failure type:\ntype1: gun tip did not contact panel during search motion (internal condition to terminate search was not met).\ntype2: exact position of detection could not be found (no distinct transition in the data).\nRemedy:  type1: ensure that panel is present. If panel is not present, touch up new point by jog or point touchup.\ntype2: confirm strength of panel. Rough indication of strength is that deflection during search motion does not exceed\n3mm.",
    "254": "SVGN-254 Low Panel Mis-detect:(Eq:%d,Ln:%d)\nCause:  Measured thickness was too large at lower panel detection.\nRemedy:  Confirm that:\n1. no obstruction exists between panel and either tip.\n2. actual panel thickness is correct.\n3. nominal thickness in pressure schedule is correct.",
    "255": "SVGN-255 Search motion is unsuccess.\nCause:  Detection data for the second upper panel search is invalid.\nRemedy:  Retry spot program touchup. Confirm that gun tip contacts panel at upper panel detection. If this problem persists after\ntaking the above actions, perform the following actions:\n1. Acquire the diagnostic data. See the procedure for diagnostic data collection at Troubleshooting section.\n2. Contact a FANUC technical representative.",
    "256": "SVGN-256 Invalid parameter in SPTCH_XXX\nCause:  Register specified for SPTCH_OFS or SPTCH_RSD is invalid.\nNote: SPTCH_OFS is attached to spot instruction to specify offset/adjustment value that is added to final offset for\npoint modification. SPTCH_RSD is attached to spot instruction to specify offset distance for robot tip.\nRemedy:  Set a valid parameter for the instruction:\n1. SPTCH_OFS: >= -2.0mm && <= 2.0mm\n2. SPTCH_RSD: >=    0.0mm && <= 20.0mm",
    "257": "SVGN-257 Invalid register number\nCause:  Parameter specified in SPTCH_OFS/SPTCH_RSD is out of range.\nRemedy:  Specify a valid register number in SPTCH_OFS or SPTCH_RSD instruction:\nmin: 1\nmax: posreg max (position registers item, on program limits setup screen)",
    "258": "SVGN-258 Spot prog touchup retry:(Num:%d)\nCause:  Initial touchup attempt failed, but retries are enabled, and touchup will be attempted again.\nRemedy:  n/a - this message is provided for information purposes only.\nNote: set maximum retry number = 0 on gun teach setup screen, to disable retries.",
    "259": "SVGN-259 Retry number > Max retry number\nCause:   Initial touchup attempt and retries failed.\nRemedy:  Confirm strength of panel. Rough indication of strength is that deflection during search motion does not exceed 3mm.\nIf panel is harder than this indication, retry spot program touchup.\nIf this problem persists after taking the above actions, perform the following actions:\n1.  Acquire the diagnostic data. See the procedure for diagnostic data collection at Chapter “20.19 Troubleshooting”\nin operator’s manual for Servo Gun Function.\n2.  Contact a FANUC technical representative.",
    "260": "SVGN-260 Search motion is unsuccess.\nCause:  Upper panel detection failed. Robot motion stopped before gun tip touched panel. Data for the detection is invalid.\nRemedy:  Retry search motion.",
    "261": "SVGN-261 Disturbance of gun is abnormal.\nCause:  Gun torque command is erratic. This gun may have mechanical issues.\nRemedy:  Examine the servo gun. Confirm that there is no actuator damage or binding. If gun is ok, retry touchup function.",
    "262": "SVGN-262 Disturbance of gun is abnormal.\nCause:  Gun torque command is erratic. This gun may have mechanical issues.\nRemedy:  Examine the servo gun. Confirm that there is no actuator damage or binding. If gun is ok, retry touchup function.",
    "263": "SVGN-263 Variation in disturbance is too much.\nCause:  Gun torque command is erratic. This gun may have mechanical issues.\nRemedy:  Examine the servo gun. Confirm that there is no actuator damage or binding. If gun is ok, retry touchup function.",
    "264": "SVGN-264 Variation in disturbance is too much.\nCause:  Gun torque command is erratic. This gun may have mechanical issues.\nRemedy:  Examine the servo gun. Confirm that there is no actuator damage or binding. If gun is ok, retry touchup function.",
    "265": "SVGN-265 Mech Comp Calib. succeeded\nCause:  Mechanical calibration for point/program touchup function completed successfully.\nRemedy:  n/a - this is a status message for informational purposes.",
    "266": "SVGN-266 Comp Dist: %s mm (%s)\nCause:  This message shows the compensation value for point/program touchup function. Value in () means    Num of\nSuccessful calibration / Specified Num of calibrations.\nRemedy:  n/a - this is a status message for informational purposes.",
    "267": "SVGN-267 Mech Comp Calib. failed\nCause:  Mechanical calibration for point/program touchup function failed. Compensation distance could not be found.\nRemedy:  Refer to SVGN-268 for cause.",
    "268": "SVGN-268 %s\nCause:  This message identifies cause of gun mechanical compensation (calibration) failure. It is posted, along with\nSVGN-267.\ninput data is invalid - parameter specified in SGKTCHCL() is invalid.\nThe remedy depends on the parameter (p1-p5) that is identified:\nInvalid gun number. Specify Gun number between 1 and $SGSYSCFG.$GUN_NUM.\nInvalid thickness: Specify thickness value greater than or equal to 1.0.\nInvalid Gun Open Distance: Specified gun tip open distance is not invalid.\nInvalid Robot Open Distance: Specified robot tip open distance is not invalid.\nInvalid Num of Calib: Calibration iterations (number) is invalid. Minimum=1\nCheck system status:Calibration cannot proceed due to system error or illegal condition.\n- Any alarm occur, and/or HOLD is turn on.\n- Enable single step and/or machine lock.\n- Disable gun stroke (mode).\n- Spot program touchup disabled.\nALL Calib. NOT SUCCESS: Calibration failed due to one of the following:\n- Alarm or HOLD occurs during calibration.\n- Misdetect error\n- Thickness out of tolerance\n- Position out of tolerance\nRemedy:  Invalid gun number. Correct gun number between 1 and $SGSYSCFG.$GUN_NUM.\nInvalid thickness: Corrct thickness value greater than or equal to 1.0.\nInvalid Gun Open Distance: Correct gun tip open distance.\nInvalid Robot Open Distance: Correct robot tip open distance.\nInvalid Num of Calib: Correct calibration iterations (number).\nCheck system status:Calibration cannot proceed due to system error or illegal condition.\n- Rest nny alarm occur, and/or HOLD.\n- Disable single step and/or machine lock.\n- Enable gun stroke (mode).\n- Enable Spot program touchup.\nALL Calib. NOT SUCCESS: Calibration failed due to one of the following:\n- Reset alarm or HOLD.\n- Identify cause of misdetect error.\n- Correct thickness for fixture.\n- Correct position for fixture.",
    "269": "SVGN-269 Spot program touchup disabled\nCause:   This indicates spot program touchup is disabled. Spot program touchup must be enabled to execute mechanical\ncompensation calibration.\nRemedy:  Enable spot program touchup via TEST CYCLE or CELL INTERFACE I/O.",
    "270": "SVGN-270 Too large torque limit.(Upper)\nCause:   Gun tip contacted upper panel surface before search motion started. Torque limit became unexpectedly-large during\nupper panel detection step1.\nRemedy:   Confirm that distance of gun panel contact is not larger than search distance. Retry spot program touchup. If gun tip\ncontacts upper panel surface before search start distance, confirm that:\n1.  no obstruction exists between guntip and panel.\nIf the above item is OK, confirm that:\n1.  nominal thickness in pressure schedule is correct.\n2.  OverThickness tolerance (on gun teach setup screen) is large enough.\nIf the above items are OK, confirm that:\n1.  Max allowable Pos error (on gun teach setup screen) is large enough.\nIf the above item is NG, the position error is made less than maximum allowable position error in the following ways.\n1.  Touch up correct position using jog or point touchup(not program touchup).",
    "271": "SVGN-271 Too large torque limit.(Lower)\nCause:  Robot tip contacted lower panel surface before search motion started. Torque limit became unexpectedly-large during\nlower panel detection.\nRemedy:  Confirm that distance of panel contact is not larger than search start distance. Retry spot program touchup. If robot tip\ncontacts lower panel surface before search start distance, increase start distance(SD) for robot tip and/or lower panel\ndetection distance. Refer to Chapter \"20.6 LOWER PANEL DETECTION DISTANCE CLAMP\" or\"20.13\nSPTCH_RSD INSTRUCTION\" in OPERATOR’S MANUAL of Servo Gun Function for more information about the\nlower panel detection distance.\nIf this problem persists after taking the above actions, perform the following actions:\n1. Acquire diagnostic data. See the procedure for diagnostic data collection at Troubleshooting section.\n2. Contact a FANUC technical representative.",
    "272": "SVGN-272 Lower Det start pos was wrong.\nCause:  Open distance of a gun axis was too short at start position of lower panel detection.\nRemedy:  Confirm that robot tip has enough clearance from panel surface at start position. If distance between robot tip and\npanel is too short, increase start distance(SD) for robot tip and/or lower panel detection distance. Refer to Chapter\n\"20.6 LOWER PANEL DETECTION DISTANCE CLAMP” or \"20.13 SPTCH_RSD INSTRUCTION\" in\nOPERATOR’S MANUAL of Servo Gun Function for more information about the lower panel detection distance.\nRetry spot program touchup.\nIf this problem persists after taking the above actions, perform the following actions:\n1. Acquire the diagnostic data. See the procedure for diagnostic data collection at Troubleshooting section.\n2. Contact a FANUC technical representative.",
    "273": "SVGN-273 Det was irregular stop.R:%d P:%d\nCause:  A gun tip was contacted an upper panel surface on a free running section before search motion.\nRemedy:  R:1 means that error occurred during upper panel detection. Confirm that gun tip has enough clearance from upper\npanel surface at start position.If distance between the tip and the panel is too short, incr ease start distance(SD) for gun\ntip.\nR:3 means that error occurred during lower panel detection. Confirm that robot tip has enough clearance from panel\nsurface at start position and that there is no obstacle between the panel and the robot tip at start position. If distance\nbetween the tip and the panel is too short, increase start distance(SD) for robot tip and/or lower panel detection\ndistance. Refer to Chapter “20.6 LOWER PANEL DETECTION DISTANCE CLAMP” or “20.13 SPTCH_RSD\nINSTRUCTION” in OPERATOR’S MANUAL of Servo Gun Function for more information about the lower panel\ndetection distance. Retry spot program touchup.\nIf this problem persists after taking the above actions, perform the following actions:\n1. Acquire diagnostic data. See the procedure for diagnostic data collection at Troubleshooting section.\n2. Contact a FANUC technical representative.\nNote: This alarm is posted when the time to execute phases2,3 take longer than anticipated, during upper1 detection\nand lower detection.\nR: Request number. R:1 is upper1 detection. R:3 is lower detection.\nP: Phase number. P:2 is phase of acceleration. P3: is phase to collect data to calculate threshold.\nIf the tip touch panel during above phase, this alarm is posted. Please check whether the tip touch panel or the gun is\nclosed(or grabbed panel) at position of search start.",
    "274": "SVGN-274 Speed threshold is too low\nCause:  Threshold to detect panel contact became unexpectedly-low.\nRemedy:  If gun tip contacted panel surface at start position, increase start distance(SD) for gun tip. If robot tip contacted lower\npanel surface at start position, increase start distance(SD) for robot tip and/or lower panel detection distance. Refer to\nChapter \"20.6 LOWER PANEL DETECTION DISTANCE CLAMP\"or \"20.13 SPTCH_RSD INSTRUCTION\" in\nOPERATOR’S MANUAL of Servo Gun Function for more information about the lower panel detection distance.Retry\nspot program touchup.\nIf this problem persists after taking the above actions, perform the following actions:",
    "275": "SVGN-275 Search starts@:%4.1fmm (%4.1f desired)\nCause:  Search start distance was clamped due to gun open limit. SVGN-275 is posted as cause code for SVGN-190. Actual\nsearch start distance is displayed, along with desired (unclamped) search start distance.\nRemedy:  See SVGN-190.",
    "276": "SVGN-276 Search mode was not selected.\nCause:  Search mode was not selected. So position detection was not done.\nRemedy:  Set $SGSYSTCH.$ACCUDET_ENB = TRUE, and then restart.",
    "278": "SVGN-278 Averaging speed is enabled.\nCause:  Axis speed will be varied during search motion. So counter-measure is turned ENABLE automatically.\nRemedy:  If the gun has no abnormality, there is no remedy.",
    "279": "SVGN-279 Averaging speed is used.\nCause:  Axis speed will be varied during search motion. So counter-measure is used automatically.\nRemedy:  If the gun has no abnormality, there is no remedy. Turn Use averaging speed ON manually if you want to disable this\nmessage.",
    "280": "SVGN-280 Excessive Wear down Comp (Gun).\nCause:  Wear down amount of gun side is exceeded to max compensation tolerance. Cap tip may be worn out and/or shank\nmay be shorter than original length. Gun axis will run over away mechanical stroke limit. And gun tip would interfere\nobject/panel if gun tip clearance is small.\nRemedy:  Chenge tip to new tip. If shank is shorter than original length, change to new shank.",
    "281": "SVGN-281 Excessive Wear down Comp (Rbt).\nCause:  Wear down amount of gun side is exceeded to max compensation tolerance. Cap tip may be worn out and/or shank\nmay be shorter than original length. Gun axis will run over away mechanical stroke limit. And gun tip would interfere\nobject/panel if gun tip clearance is small.\nRemedy:  Chenge tip to new tip. If shank is shorter than original length, change to new shank.",
    "282": "SVGN-282 Wear ratio updated:%s->%s\nCause:  Wear ratio was updated. Displayed value means old wear ratio -> new wear ratio.\nRemedy:  This is just information. There is no remedy.",
    "283": "SVGN-283 Wear ratio(%s) Not updated\nCause:  Wear ratio was updated. (However wear down was updated ) System can not calcarate when tips are not\nWORN.DOWN( = cap tip is increased ). There are some causes.\n- Cap has been replaced. But new tip flag is OFF.\n- Cap wear has been hardly changing. Wear ratio could not be updated in too short cycle.\nSee SVGN-284 to confirm wear down changing.\nRemedy:  Turn on new tip when tip is replaced in next time.Also Perform 2step after tip dressing several times.",
    "284": "SVGN-284 Gun:%s,Rbt:%s\nCause:  This indicates wear down changing:\nThe last 2step wear down -> Current 2step wear down.If The last 2step wear down is larger than current 2step wear\ndown, tip would be replaced.If cap wear has been hardly changing, 2 step is performed with too short cycle.\nRemedy:  Turn on new tip when tip is replaced in next time. Also Perform 2step after tip dressing several times.",
    "285": "SVGN-285 Wear ratio Out of Tolerance\nCause:  This indicates calcurated wear down is exceeded users tolerance.\n- Cap has been replaced. But new tip flag is OFF.\n- Cap wear has been hardly changing. Wear ratio could not be updated in too short cycle.\nRemedy:  Turn on new tip when tip is replaced in next time. Also Perform 2step after tip dressing several times. Users tolerance\ncan be chenged in TWD setup screen.",
    "286": "SVGN-286 Wear ratio:%s > Max:%s\nCause:  This indicates calcurated wear down and users tolerance(Max).\nRemedy:  See SVGN-285.",
    "287": "SVGN-287 Wear ratio:%s < Min:%s\nCause:  This indicates calcurated wear down and users tolerance(Min).\nRemedy:  See SVGN-285.",
    "288": "SVGN-288 New tip !! Use 2step TWD\nCause:  1step performed with new tip flag. Do not perform 1step with new tip falg when auto update wear ratio is enable.\nRemedy:  Perform 2step with new tip flag again.",
    "289": "SVGN-289 Update Wear ratio\nCause:  Wear ratio has not been updated for long time.\nRemedy:  Please update wear ratio.",
    "290": "SVGN-290 Do press calib over again:G%d\nCause:  There is mistake in the setting at pressure calibration.\nRemedy:  Execute pressure calibration again.",
    "291": "SVGN-291 Illegal temperature compens val:G%d\nCause:  Temperature compensation value is too large. Therefore, pressure was not able to be compensated.\nRemedy:  Confirm the content of the setup of temperature compensation function.",
    "292": "SVGN-292 Invalid AI,GI conversion factor:G%d\nCause:  Invalid AI,GI conversion factor setting is not correct.\nRemedy:  Confirm the AI,GI conversion factor setting.",
    "293": "SVGN-293 Temp info from motor isnt obtained:G%d\nCause:  Temperature information cannot be obtained from this pulse corder.\nRemedy:  Examine the figure number for the pulse corder. Examine whether the pulse coda is breakdown.",
    "294": "SVGN-294 Temp exceed abnormal up lim:G%d\nCause:  Temperature exceeded abnormal motor temperature upper limit value.\nRemedy:  Confirm the temperature sensor is not out of order.",
    "295": "SVGN-295 Temp below abnormal low lim:G%d\nCause:  Temperature fell below abnormal motor temperature lower limit value.\nRemedy:  Confirm the temperature sensor is not out of order.",
    "296": "SVGN-296 Invalid temperature coefficient:G%d\nCause:  Temperature coefficient setting is not correct.\nRemedy:  Confirm the temperature coefficient setting.",
    "297": "SVGN-297 Temp info from AI isnt obtained:G%d\nCause:  Temperature information cannot be obtained from AI.\nRemedy:  Confirm the AI setting.",
    "298": "SVGN-298 Temp info from GI isnt obtained:G%d\nCause:  Temperature information cannot be obtained from GI.\nRemedy:  Confirm the GI setting.",
    "299": "SVGN-299 Invalid thickness: t=**\nCause:  Instruction for which invalid thickness was specified was executed.\nRemedy:  Confirm the thickness in the instruction.",
    "300": "SVGN-300 Early welding OFF at resuming\nCause:  Program is paused when gun is closing with early welding. Early welding is disabled for resumed gun closing.",
    "301": "SVGN-301 Early weld calibration INCOMP\nCause:  Early weld calibration is incomplete. Early welding can not be enabled.\nRemedy:  Execute early weld calibration on gun setup utiltiy screen.",
    "302": "SVGN-302 Welding in pressure stortage\nCause:  When pressure did not reach target pressure, weld init would asserted in pressure shortage.\nRemedy:  Please refer to remedy of SVGN-020. Also, Execute early weld calibration again.",
    "303": "SVGN-303 Gun%d: Disabled early welding\nCause:  In pressure of dual gun, either gun disable early welding. Weld init will assert when pressure of gun that disables early\nwelding rearches target pressure.\nRemedy:  Enable/Disable early welding for both gun.",
    "304": "SVGN-304 Invalid early welding time\nCause:  Invalid early welding time was specified. Early welding time is too large.\nRemedy:  Correct early welding time. Early welding time can not larger than torque up time of gun.",
    "305": "SVGN-305 OVR < 100%%,Early Welding Disabled\nCause:  General override is not 100%. Early welding time can work correctly with OVR 100%.\nRemedy:  Set override 100%.",
    "306": "SVGN-306 Thickness Check Calib Retrying...\nCause:  Retrying thickness check calibration.\nRemedy:  This message is provided for informational purposes only, it is not a fault.",
    "340": "SVGN-340 Prog:%s is write-protected.\nCause:  Spot program touchup function could not modify program position, because file is write-protected.\nRemedy:  Disable write protection.",
    "341": "SVGN-341 Spot program touchup pending.\nCause:  Spot program touchup has been enabled with execution mode = TOUCHUP mode during spot instruction execution, so\nspot program touchup will not start until next spot. Conditions leading to this message:\n1. Start program with spot program touchup disabled.\n2. Pause program during execution of spot instruction.\n3. Enable spot program touchup (in TOUCHUP mode).\n4. Resume (continue) program.\nRemedy:  Note: purpose of this warning is operator notification, this is not a fault condition. In order to execute program touchup\nimmediately, either execute shift backward (to restart spot) or abort program.",
    "342": "SVGN-342 Spot program verification enabled !\nCause:  A tp program started (or resumed) and spot program touchup function is enabled with execution mode = VERIFY.\nVerify mode means that points will be evaluated but positions will NOT be modified.\nRemedy:  If touchup (not verify) mode is desired, change execution mode via Touchup setup screen:\na. if tp is disabled, set Execution mode for AUTO = TOUCHUP mode,\nb. if tp is enabled, set Execution mode for TEACH = TOUCHUP mode,\nIf normal spot (not touchup or verify) operation is desired, disable program touchup via:\na. DIN, if tp is enabled.\nb. Touchup mode setup screen, if tp is disabled.",
    "343": "SVGN-343 Spot program verification pending.\nCause:  Spot program touchup has been enabled in VERIFY mode during spot instruction execution, so spot program touchup\nwill not start until next spot. Conditions leading to this case are:\n1. Start program with spot program touchup disabled.\n2. Pause program during execution of spot instruction.",
    "344": "SVGN-344 Torque calibration incomplete.\nCause:  Touchup was requested with torque control type 2, but torque calibration is incomplete.\nRemedy:  Complete touchup torque calibration or change $sggun#.$tchup.$updt_tq_typ=1 and $sggun#.$tchup.$updt_tq_typ=1.",
    "345": "SVGN-345 Prog(%s): Read group msk failed.\nCause:  Group mask could not read from specified program().Refer to cause code (SVGN-347) for reason.\nRemedy:  Lookup error code for SVGN-347 and take appropriate action.",
    "346": "SVGN-346 Prog(%s): Write group msk failed.\nCause:  Group mask could not be written to specified program().Refer to cause code (SVGN-347) for reason.\nRemedy:  Lookup error code for SVGN-347 and take appropriate action.",
    "347": "SVGN-347 status:%s.\nCause:  SVGN application alarm has occurred. This message merely reports the status (error) number that caused this problem.\nRemedy:  Lookup error code and take appropriate action.",
    "349": "SVGN-349 Thickness not recorded.\nCause:  Thickness is not recorded.\nRemedy:  Refer to the error cause code.",
    "350": "SVGN-350 Pressure release aborted.\nCause:  Fault occurred or shift key was released while pressure release progress was active.\nRemedy:  Correct reason for fault and/or do not release shift key during pressure release.",
    "370": "SVGN-370 Contact position is not correct\nCause:  Gun tip contacted panel sooner than expected - either settings are incorrect or wrong panel is present. If correct panel\nis present, then confirm that following items are correct:\n1. Thickness value\n2. Gun Zero Master position\n3. Gear ratio (tip displacement)\nRemedy:  1. If thickness is incorrect, set proper thickness value in spot/pres_motn instruction.\n2. If gun zero master is incorrect, go to servogun master screen and execute master or automaster.\n3. If gear ratio is incorrect, go to gun setup util and set gun specs.",
    "371": "SVGN-371 Invalid Pressure Gain Tuning\nCause:  Internal Servo Gun error.\nRemedy:  Record error and report to hotline.",
    "372": "SVGN-372 Uninitialized thickness: t=**\nCause:  Thickness is not initialised at SPOT, PRESS_MOTN, TIPDRESS instructions.\nRemedy:  Set the part or dresser thickness to appropriate value.",
    "373": "SVGN-373 Gun open required for autotuning.\nCause:  Gun is pressuring (closed past 0). Auto tune can not start because pressure control is active.\nRemedy:  Jog gun open to release pressure, then restart autotuning.",
    "374": "SVGN-374 Wear ratio update Locked.\nCause:  1 step measurement was performed with new tip. Wear ratio updating is loacked.\nRemedy:  To update wear ratio, 2 step measurement must be performed with new tip. This locking is released by 2 step\nmeasurment. SVGN-288 is posted as cause code,it needs twice 2 step measurement with currenct tip to update wear\nratio. SVGN-375 is posted as cause code, next 2 step measurement update wear ratio.",
    "375": "SVGN-375 Next 2step TWD updates wear ratio.\nCause:  2 step measurement was performed after 1 step measurement has been performed with new tip.\nRemedy:  No remedy.",
    "376": "SVGN-376 Internal program error LBL:%d\nCause:  Internal servogun program error.\nRemedy:  Repower, go to control start, and then back to cold start. Record the error and report to hotline, if the problem persists.",
    "377": "SVGN-377 Repower required for autocont fn\nCause:  Repower required for auto continue function.\nRemedy:  Repower, go to control start, and then back to cold start.",
    "378": "SVGN-378 Thickness measurement cancelled.\nCause:  (None)\nRemedy:  (None)",
    "379": "SVGN-379 Thickness table is empty.\nCause:  Shift hardkey was pressed (to change manual pressure) but all values in thickness table are uninitialized.\nRemedy:  Set one (or more) values into the thickness table.",
    "380": "SVGN-380 Thickness table value/index is invalid.\nCause:  Shift+Gun hardkey was pressed (to execute manual pressure operation) but thickness index and/or thickness value are\ninvalid.\nRemedy:  Set one (or more) values into the thickness table and select a valid thickness by pressing Gun hardkey.",
    "381": "SVGN-381 Thick:%.1fmm, Press:%d%s, deflct:%.1fmm\nCause:  This message is posted because thickness measurement was performed, and\n$SGCFG[].$THKMESCFG.$ALM4MESINFO = TRUE. This message merely provides a record of thickness\nmeasurment in the alarm log. It is not a fault/abnormal condition. Note: SVGN-176 is provided as cause code for this\nmessage to identify origin of thickness measurement request:\nEditor, Manual weld screen, thickness table screen, or Pressure Calibration screen.\nRemedy:  Set $SGCFG[].$THKMESCFG.$ALM4MESINFO = FALSE to disable this message.",
    "382": "SVGN-382 Tip could not contact with specified speed\nCause:  When tip contacted, the gun speed is not specified speed in pressure calibration. If Contact speed is not specified speed\nin pressure calibration, the calibrated pressure is not re-producted, there may be slight error. Basic cause is that tip\nopening distance before pressure is not enough long to achieve specified speed. There are some factor for this cause.\n- Specified tip distance is small in SD condtion.\n- And/or there is error of teaching position.\n- And/or mastering postion is not correct.\n- And/or thickness value is not correct.\nRemedy:  Confirm tip opening before pressure. And/or confirm teaching position, gun mastering,and thickness. If weld quality is\nno problem, this warning could be ignored.",
    "383": "SVGN-383 Extra group motion.\nCause:  When extra groups are used in a robot + servogun program, motion of an extra group was detected during SPOT\nmotion.\nRemedy:  Do not allow extra groups to move during SPOT motion.",
    "385": "SVGN-385 Prg tch mode swich err.\nCause:  Spot program touchup mode had become ENABLE immediately before spot instruction is executed.\nRemedy:  Make the spot program touchup mode ENABLE earlier.",
    "386": "SVGN-386 Robot bkup clamped:%.1fmm(%.1fdesired).\nCause:  Requested robot backup distance cannot be provided, due to gun open limit. Actual robot backup provided is noted in\nthe alarm.\nRemedy:  1. Increase gun open limit if possible.\n2. Reduce robot backup distance.",
    "387": "SVGN-387 Increase sglogarr size to log data.\nCause:  Tune log and/or press log are enabled, but sglogarr size <= 1. Tune log and press log data files are created only if\nsglogarr size > 1.\nRemedy:  If Log data is needed, set $SGSYSCFG.$SGLOGARRSZ > 1, and repower. Set size based on maximum sample\nduration. For example, a size of 1000 provides 1000*8ms or 8 seconds worth of data. If log data is NOT needed, set\n$SGLOGCFG.$TUN_LOG_ENB=FALSE and $SGLOGCFG.$PRS_LOG_ENB=FALSE.",
    "388": "SVGN-388 Speed noise(%.1fmm/sec) > expected(%.1f):%d.\nCause:  Variation in speed during observation period (before detection), is larger than speed variation observed during\ncalibration. Number at end of message indicates phase: 1=Upper panel detection, 2=Lower panel detection.\nRoot causes are:\n1. Gun mechanical characteristics have changed or calibration is not up to date.\n2. Current orientation is different than orientation used during calibration.\n3. Open distance for current panel detection > open distance used during calibration.\nRemedy:  1. Redo calibration.\n2. if problem persists, increase value of $SGSYSTCH.$P0SPDALMMGN.",
    "389": "SVGN-389 Press noise(%.1fkgf) > expected(%.1f):%d.\nCause:  Pressure variation during observation period (before detection), is larger than pressure variation observed during\ncalibration. Number at end of message indicates phase: 1=Upper panel detection, 2=Lower panel detection.\nRoot causes are:\n1. Gun mechanical characteristics have changed or calibration is not up to date.\n2. Current orientation is different than orientation used during calibration.\n3. Open distance at panel detection > open distance used during calibration.\nRemedy:  1. Redo calibration.\n2. if problem persists, increase value of $SGSYSTCH.$P0TRQALMMGN.",
    "390": "SVGN-390 Gun mode change detected while welding.\nCause:  Stroke/No Stroke mode might have been changed while executing spot welding program.\nRemedy:  To prevent spot welding point being skipped, the robot paused. Confirm Stroke/No Stroke mode.",
    "392": "SVGN-392 This TW**.TP is not supported.\nCause:  This TWD program is for R-J3iB controller. R-30iB controller does not supported this.\nRemedy:  Replace TW***.TP to TWK***.PC such as the following. Refer to FANUC Robot series R-30iB CONTROLLER\nServo Gun Function OPERATOR’S MANUAL (B-83264EN).\nTW0THOLD => TWKTHOLD, TW1MTCLB => TWKZRCLB, TW1MTFIX => TWKFXTCH\nTW2WDCLB => TWKZRCLB, TW2WDFIX => TWKFXTCH, TW3RSCLB => TWKRSCLB"
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = data;
  if (global.FanucAlarms) global.FanucAlarms._put("SVGN", data);
})(typeof window !== 'undefined' ? window : globalThis);
